11	#ifndef WORKSPACE_QUEUE_H
12	#define WORKSPACE_QUEUE_H
13	
14	#include "kernel_operator.h"
15	
16	// Canonical implementation — also duplicated in
17	// quant_matmul/kernel/workspace_queue.h. Keep both in sync.
18	
19	/**
20	 * Ring buffer over workspace GM for AIC (cube) -> AIV (vector) data transfer.
21	 *
22	 * Producer (AIC) writes slots via Fixpipe, consumer (AIV) reads via MTE2.
23	 * Synchronization uses CrossCoreSetFlag/WaitFlag mode 0x2 (AIC <-> AIV).
24	 *
25	 * Usage:
26	 *   WorkspaceQueue<float, 4> queue;
27	 *   queue.Init(workspace, slotSize, CUBE_FLAG_ID, VECTOR_FLAG_ID);
28	 *
29	 *   // AIV init: mark all slots free
30	 *   if ASCEND_IS_AIV { queue.InitFreeSlots(); }
31	 *
32	 *   // AIC producer loop:
33	 *   auto slot = queue.ProducerAcquire();   // wait free, get slot
34	 *   Fixpipe(slot, ...);                    // write data
35	 *   queue.ProducerRelease();               // signal data ready
36	 *
37	 *   // AIV consumer loop:
38	 *   auto slot = queue.ConsumerAcquire();   // wait data ready, get slot
39	 *   DataCopy(local, slot, ...);            // read data
40	 *   queue.ConsumerRelease();               // signal slot free
41	 */
42	template <typename T, uint32_t DEPTH>
43	class WorkspaceQueue {
44	public:
45	    __aicore__ inline WorkspaceQueue() {}
46	
47	    __aicore__ inline void Init(GM_ADDR workspace, uint32_t slotSize,
48	                                uint16_t cubeNotifyVecId, uint16_t vecNotifyCubeId);
49	
50	    // AIV calls at init to mark all slots as free
51	    __aicore__ inline void InitFreeSlots();
52	
53	    // Producer (AIC): wait for free slot, return its GlobalTensor
54	    __aicore__ inline AscendC::GlobalTensor<T> ProducerAcquire();
55	    // Producer (AIC): signal data ready, advance to next slot
56	    __aicore__ inline void ProducerRelease();
57	
58	    // Consumer (AIV): wait for data ready, return its GlobalTensor
59	    __aicore__ inline AscendC::GlobalTensor<T> ConsumerAcquire();
60	    // Consumer (AIV): signal slot free, advance to next slot
61	    __aicore__ inline void ConsumerRelease();
62	
63	private:
64	    AscendC::GlobalTensor<T> workspace_;
65	    uint32_t slotSize_;
66	    uint32_t head_;  // producer write index
67	    uint32_t tail_;  // consumer read index
68	    uint16_t cubeNotifyVecId_;
69	    uint16_t vecNotifyCubeId_;
70	};
71	
72	template <typename T, uint32_t DEPTH>
73	__aicore__ inline void WorkspaceQueue<T, DEPTH>::Init(
74	    GM_ADDR workspace, uint32_t slotSize,
75	    uint16_t cubeNotifyVecId, uint16_t vecNotifyCubeId)
76	{
77	    slotSize_ = slotSize;
78	    head_ = 0;
79	    tail_ = 0;
80	    cubeNotifyVecId_ = cubeNotifyVecId;
81	    vecNotifyCubeId_ = vecNotifyCubeId;
82	    workspace_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(workspace), DEPTH * slotSize);
83	}
84	
85	template <typename T, uint32_t DEPTH>
86	__aicore__ inline void WorkspaceQueue<T, DEPTH>::InitFreeSlots()
87	{
88	    for (uint32_t i = 0; i < DEPTH; ++i) {
89	        AscendC::CrossCoreSetFlag<0x2, PIPE_MTE2>(vecNotifyCubeId_);
90	    }
91	}
92	
93	template <typename T, uint32_t DEPTH>
94	__aicore__ inline AscendC::GlobalTensor<T> WorkspaceQueue<T, DEPTH>::ProducerAcquire()
95	{
96	    AscendC::CrossCoreWaitFlag<0x2>(vecNotifyCubeId_);
97	    return workspace_[head_ % DEPTH * slotSize_];
98	}
99	
100	template <typename T, uint32_t DEPTH>
101	__aicore__ inline void WorkspaceQueue<T, DEPTH>::ProducerRelease()
102	{
103	    AscendC::CrossCoreSetFlag<0x2, PIPE_FIX>(cubeNotifyVecId_);
104	    head_++;
105	}
106	
107	template <typename T, uint32_t DEPTH>
108	__aicore__ inline AscendC::GlobalTensor<T> WorkspaceQueue<T, DEPTH>::ConsumerAcquire()
109	{
110	    AscendC::CrossCoreWaitFlag<0x2>(cubeNotifyVecId_);
111	    return workspace_[tail_ % DEPTH * slotSize_];
112	}
113	
114	template <typename T, uint32_t DEPTH>
115	__aicore__ inline void WorkspaceQueue<T, DEPTH>::ConsumerRelease()
116	{
117	    AscendC::CrossCoreSetFlag<0x2, PIPE_MTE2>(vecNotifyCubeId_);
118	    tail_++;
119	}
120	
121	#endif // WORKSPACE_QUEUE_H

