28	template <typename aType, typename bType, typename cType>
29	class MatmulKernel : public MatmulKernelBase<MatmulKernel<aType, bType, cType>, aType, bType, cType> {
30	    uint32_t base_m() const { return baseM_; }
31	    uint32_t base_n() const { return baseN_; }
32	    uint32_t base_k() const { return baseK_; }
33	    uint32_t base_mk() const { return baseMK_; }
34	    uint32_t base_kn() const { return baseKN_; }
35	    uint32_t base_mn() const { return baseMN_; }
36	    uint32_t l1_prefetch() const { return l1Prefetch_; }
37	
38	    friend class MatmulKernelBase<MatmulKernel<aType, bType, cType>, aType, bType, cType>;
39	
40	    uint32_t l1Prefetch_;
41	    uint32_t baseM_, baseN_, baseK_;
42	    uint32_t baseMK_, baseKN_, baseMN_;
43	
44	public:
45	    __aicore__ inline MatmulKernel() {}
46	    __aicore__ inline void Init(uint32_t k, uint32_t lda, uint32_t ldb,
47	                                uint32_t baseM, uint32_t baseN, uint32_t baseK,
48	                                uint32_t l1Prefetch,
49	                                AscendC::TPipe &pipe);
50	};
51	
52	template <typename aType, typename bType, typename cType>
53	__aicore__ inline void MatmulKernel<aType, bType, cType>::Init(
54	    uint32_t k, uint32_t lda, uint32_t ldb,
55	    uint32_t baseM, uint32_t baseN, uint32_t baseK,
56	    uint32_t l1Prefetch,
57	    AscendC::TPipe &pipe)
58	{
59	    ASSERT(k % baseK == 0);
60	
61	    l1Prefetch_ = l1Prefetch;
62	    baseM_ = baseM;
63	    baseN_ = baseN;
64	    baseK_ = baseK;
65	    baseMK_ = baseM_ * baseK_;
66	    baseKN_ = baseK_ * baseN_;
67	    baseMN_ = baseM_ * baseN_;
68	    this->k_ = k;
69	    this->a_dvalue_ = lda;
70	    this->b_dvalue_ = ldb;
71	
72	    pipe.InitBuffer(this->inQueueA1, 2, baseMK_ * l1Prefetch_ * sizeof(aType));
73	    pipe.InitBuffer(this->inQueueA2, 2, baseMK_ * sizeof(aType));
74	    pipe.InitBuffer(this->inQueueB1, 2, baseKN_ * l1Prefetch_ * sizeof(bType));
75	    pipe.InitBuffer(this->inQueueB2, 2, baseKN_ * sizeof(bType));
76	    pipe.InitBuffer(this->outQueueCO1, 1, baseMN_ * sizeof(cType));
77	}
78	
79	#endif // MATMUL_CUSTOM_H
