#ifndef FLASH_ATTENTION_SCORE_KERNEL_H
#define FLASH_ATTENTION_SCORE_KERNEL_H

#include "kernel_operator.h"
#include "workspace_queue.h"

using namespace AscendC;

// -------------------- Tiling Data --------------------
constexpr int32_t DEFAULT_BASE_K = 128;    // Cube tiling along K dimension
constexpr int32_t DEFAULT_BASE_N = 128;    // Cube tiling along N dimension (for P@V output)
constexpr int32_t WORKSPACE_DEPTH = 3;     // Ring buffer depth = prelaunch + 1
constexpr int32_t PRELAUNCH = 2;

#pragma pack(push, 8)
struct FlashAttentionTiling {
    int32_t batch;
    int32_t seq_len;
    int32_t dim;
    int32_t block_m;
    int32_t block_n;
    int32_t kv_loops;
    int32_t m_blocks;       // seq_len / block_m
    int32_t total_cores;    // m_blocks * batch
    float scale_value;
};
#pragma pack(pop)

// Cross-core flag IDs
#define CUBE_FLAG_S     0x8   // Cube→Vector: S ready
#define VECTOR_FLAG_S   0x9   // Vector→Cube: S slot free
#define CUBE_FLAG_P     0xA   // Cube→Vector: P is needed (notify C2)
#define VECTOR_FLAG_P   0xB   // Vector→Cube: P ready
#define CUBE_FLAG_O     0xC   // Cube→Vector: O_tmp ready
#define VECTOR_FLAG_O   0xD   // Vector→Cube: O_tmp slot free

// -------------------- CopyTiling helper --------------------
__aicore__ inline void CopyTiling(FlashAttentionTiling *tiling, GM_ADDR tilingGM)
{
    int32_t *ptr = reinterpret_cast<int32_t *>(tiling);
    auto tiling32 = reinterpret_cast<__gm__ int32_t *>(tilingGM);
    uint32_t numInts = sizeof(FlashAttentionTiling) / sizeof(int32_t);
    for (uint32_t i = 0; i < numInts; ++i, ++ptr) {
        *ptr = tiling32[i];
    }
}

// -------------------- Nd2Nz helper for GM→L1 --------------------
template<typename T>
__aicore__ inline void LoadNdGmToNzL1(const LocalTensor<T> &dst,
                                       const GlobalTensor<T> &src,
                                       uint32_t m, uint32_t n, uint32_t ld)
{
    Nd2NzParams params;
    params.ndNum = 1;
    params.nValue = m;
    params.dValue = n;
    params.srcNdMatrixStride = 0;
    params.srcDValue = ld;
    params.dstNzC0Stride = m;
    params.dstNzNStride = 1;
    params.dstNzMatrixStride = 0;
    DataCopy(dst, src, params);
}

// -------------------- NzL1→ZzL0A helper --------------------
template<typename T>
__aicore__ inline void LoadNzL1ToZzL0A(const LocalTensor<T> &dst,
                                        const LocalTensor<T> &src,
                                        uint32_t m, uint32_t k, uint32_t colC0Stride)
{
    LoadData3DParamsV2<T> params;
    params.l1H = 1;
    params.l1W = colC0Stride;
    params.channelSize = k;
    params.kExtension = k;
    params.mExtension = m;
    params.strideH = 1;
    params.strideW = 1;
    params.filterH = 1;
    params.filterW = 1;
    params.dilationFilterH = 1;
    params.dilationFilterW = 1;
    LoadData(dst, src, params);
}

// -------------------- NzL1→ZnL0B helper --------------------
template<typename T>
__aicore__ inline void LoadNzL1ToZnL0B(const LocalTensor<T> &dst,
                                        const LocalTensor<T> &src,
                                        uint32_t k, uint32_t n, uint32_t colC0Stride)
{
    LoadData3DParamsV2<T> params;
    params.l1H = 1;
    params.l1W = colC0Stride;
    params.channelSize = n;
    params.kExtension = n;
    params.mExtension = k;
    params.strideH = 1;
    params.strideW = 1;
    params.filterH = 1;
    params.filterW = 1;
    params.dilationFilterH = 1;
    params.dilationFilterW = 1;
    LoadData(dst, src, params);
}

// -------------------- Fixpipe L0C→GM(Nd) helper --------------------
template<typename T>
__aicore__ inline void FixpipeNzL0cToNdGm(const GlobalTensor<T> &dst,
                                           const LocalTensor<T> &src,
                                           uint32_t m, uint32_t n)
{
    FixpipeParamsV220 params;
    params.nSize = n;
    params.mSize = m;
    params.srcStride = m;
    params.dstStride = n;
    params.ndNum = 1;
    params.srcNdStride = 0;
    params.dstNdStride = 0;
    Fixpipe(dst, src, params);
}

// -------------------- Main Kernel Class --------------------
class FlashAttentionScoreKernel {
public:
    __aicore__ inline FlashAttentionScoreKernel() {}
    __aicore__ inline void Init(GM_ADDR q, GM_ADDR k, GM_ADDR v, GM_ADDR output,
                                GM_ADDR ws_s, GM_ADDR ws_p, GM_ADDR ws_o,
                                GM_ADDR tilingGM, TPipe *pipe);
    __aicore__ inline void Process();

private:
    // Tiling params
    FlashAttentionTiling tiling_;
    int32_t batch_, seq_len_, dim_, block_m_, block_n_, kv_loops_, m_blocks_;
    int32_t bx_, bz_;  // seq block index, batch index
    float scale_;
    int32_t half_m_;   // block_m / 2 (for AIV sub-block)

    // Global memory tensors
    GlobalTensor<half> qGM_, kGM_, vGM_, outGM_;

    // Workspace queues (ring buffers)
    WorkspaceQueue<float, WORKSPACE_DEPTH> wsQueueS_;    // Cube→Vector, S scores (float32)
    WorkspaceQueue<half, WORKSPACE_DEPTH> wsQueueP_;     // Vector→Cube, P = softmax(S) (half)
    WorkspaceQueue<float, WORKSPACE_DEPTH> wsQueueO_;    // Cube→Vector, O_tmp (float32)
    GlobalTensor<float> wsMetaGM_;                       // [block_m, 2] per slot, Vector→Vector (UB stored)

    // --- AIC (Cube) buffers ---
    // L1 buffers
    TQue<TPosition::A1, 1> qL1Queue_;
    TQue<TPosition::B1, 1> kL1Queue_;
    TQue<TPosition::B1, 1> vL1Queue_;
    TQue<TPosition::A1, 1> pL1Queue_;

    // L0A/L0B queues
    TQue<TPosition::A2, 1> qA2Queue_;
    TQue<TPosition::B2, 1> kB2Queue_;
    TQue<TPosition::B2, 1> vB2Queue_;
    TQue<TPosition::A2, 1> pA2Queue_;

    // L0C for matmul results
    TQue<TPosition::CO1, 1> co1QueueS_;   // S accumulator [block_m, block_n]
    TQue<TPosition::CO1, 1> co1QueueO_;   // O accumulator [block_m, dim]

    // --- AIV (Vector) buffers ---
    // Input/output queues
    TQue<TPosition::VECIN, 1> vinQueue_;
    TQue<TPosition::VECOUT, 1> voutQueue_;

    // Compute buffers (TBuf for float32 intermediates)
    TBuf<TPosition::VECCALC> accOBuf_;      // [half_m, dim] running accumulator
    TBuf<TPosition::VECCALC> sumexpBuf_;    // [half_m] running sumexp
    TBuf<TPosition::VECCALC> miBuf_;        // [half_m] running max

    TBuf<TPosition::VECCALC> sScoreBuf_;    // [half_m, block_n] S * scale
    TBuf<TPosition::VECCALC> miPrevBuf_;    // [half_m] previous max
    TBuf<TPosition::VECCALC> sTmpBuf_;      // [half_m, block_n] temp S copy
    TBuf<TPosition::VECCALC> reduceWork_;   // reduce workspace
    TBuf<TPosition::VECCALC> sumexpIBuf_;   // [half_m] per-step sumexp
    TBuf<TPosition::VECCALC> accOOpsBuf_;   // [half_m, dim] O_tmp from consumer
    TBuf<TPosition::VECCALC> alphaBuf_;     // [half_m] rescaling alpha

    // Sizes
    int32_t szQ_;     // block_m * dim
    int32_t szK_;     // block_n * dim
    int32_t szV_;     // block_n * dim
    int32_t szP_;     // block_m * block_n
    int32_t szS_;     // block_m * block_n (float)
    int32_t szO_;     // block_m * dim (float)
    int32_t szHalfM_; // half_m * dim
    int32_t szHalfO_; // half_m * dim * sizeof(float) for accumulate
    int32_t szRow_;   // half_m
    int32_t szHalfRowS_; // half_m * block_n
    int32_t szReduceWork_; // reduce workspace

    // Pipeline functions
    __aicore__ inline void CubeInit();
    __aicore__ inline void VectorInit();
    __aicore__ inline void CubeProdStep(int32_t t);
    __aicore__ inline void VectorProdStep(int32_t t);
    __aicore__ inline void CubeConsStep(int32_t now_k);
    __aicore__ inline void VectorConsStep(int32_t now_k);
    __aicore__ inline void VectorEpilogue();

    // Sub-matmul: S = Q[block_m, dim] @ K^T[dim, block_n]
    __aicore__ inline void MatmulQKT(LocalTensor<half> &qL1, LocalTensor<half> &kL1,
                                      LocalTensor<float> &sL0C, bool init);
    // Sub-matmul: O_tmp = P[block_m, block_n] @ V[block_n, dim]
    __aicore__ inline void MatmulPV(LocalTensor<half> &pL1, LocalTensor<half> &vL1,
                                     LocalTensor<float> &oL0C, bool init);
};

// ===================== Init =====================
__aicore__ inline void FlashAttentionScoreKernel::Init(
    GM_ADDR q, GM_ADDR k, GM_ADDR v, GM_ADDR output,
    GM_ADDR ws_s, GM_ADDR ws_p, GM_ADDR ws_o,
    GM_ADDR tilingGM, TPipe *pipe)
{
    // Read tiling
    CopyTiling(&tiling_, tilingGM);
    batch_   = tiling_.batch;
    seq_len_ = tiling_.seq_len;
    dim_     = tiling_.dim;
    block_m_ = tiling_.block_m;
    block_n_ = tiling_.block_n;
    kv_loops_ = tiling_.kv_loops;
    m_blocks_ = tiling_.m_blocks;
    scale_   = tiling_.scale_value;

    int32_t coreIdx = GetBlockIdx() / GetSubBlockNum();
    bz_ = coreIdx / m_blocks_;
    bx_ = coreIdx % m_blocks_;
    half_m_ = block_m_ / 2;

    // Sizes
    szQ_ = block_m_ * dim_;
    szK_ = block_n_ * dim_;
    szV_ = block_n_ * dim_;
    szP_ = block_m_ * block_n_;
    szS_ = block_m_ * block_n_;
    szO_ = block_m_ * dim_;
    szHalfM_ = half_m_ * dim_;
    szHalfO_ = half_m_ * dim_ * sizeof(float);
    szRow_ = half_m_;
    szHalfRowS_ = half_m_ * block_n_;
    szReduceWork_ = half_m_ * block_n_ * sizeof(float) * 3 / 4; // ~75% of tile

    // Set global buffers
    qGM_.SetGlobalBuffer(reinterpret_cast<__gm__ half *>(q), batch_ * seq_len_ * dim_);
    kGM_.SetGlobalBuffer(reinterpret_cast<__gm__ half *>(k), batch_ * seq_len_ * dim_);
    vGM_.SetGlobalBuffer(reinterpret_cast<__gm__ half *>(v), batch_ * seq_len_ * dim_);
    outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ half *>(output), batch_ * seq_len_ * dim_);

    // Init workspace queues (Cube→Vector for S)
    uint32_t wsSOffset = coreIdx * WORKSPACE_DEPTH * szS_;
    wsQueueS_.Init(ws_s + wsSOffset * sizeof(float), szS_,
                   CUBE_FLAG_S, VECTOR_FLAG_S);

    // Init workspace queues (Vector→Cube for P) — P written by AIV via DataCopy, read by AIC
    uint32_t wsPOffset = coreIdx * WORKSPACE_DEPTH * szP_;
    wsQueueP_.Init(ws_p + wsPOffset * sizeof(half), szP_,
                   CUBE_FLAG_P, VECTOR_FLAG_P);

    // Init workspace queues (Cube→Vector for O_tmp)
    uint32_t wsOOffset = coreIdx * WORKSPACE_DEPTH * szO_;
    wsQueueO_.Init(ws_o + wsOOffset * sizeof(float), szO_,
                   CUBE_FLAG_O, VECTOR_FLAG_O);

    // Init AIC and AIV
    if ASCEND_IS_AIC {
        CubeInit();
    }

    if ASCEND_IS_AIV {
        VectorInit();
    }
}

__aicore__ inline void FlashAttentionScoreKernel::CubeInit()
{
    // Get TPipe reference
    TPipe *pipe = &AscendC::GetPipe();
    // L1 buffers: Q [block_m, dim], K [block_n, dim], V [block_n, dim], P [block_m, block_n]
    pipe->InitBuffer(qL1Queue_, 1, szQ_ * sizeof(half));
    pipe->InitBuffer(kL1Queue_, 1, szK_ * sizeof(half));
    pipe->InitBuffer(vL1Queue_, 1, szV_ * sizeof(half));
    pipe->InitBuffer(pL1Queue_, 1, szP_ * sizeof(half));

    // L0A/L0B buffers: sized for baseK/baseN tiles
    int32_t tileA = block_m_ * DEFAULT_BASE_K;  // Q tile: [block_m, baseK]
    int32_t tileB = block_n_ * DEFAULT_BASE_K;  // K tile: [block_n, baseK]
    int32_t tileA2 = block_m_ * block_n_;        // P tile: [block_m, block_n]
    int32_t tileB2 = block_n_ * DEFAULT_BASE_N;  // V tile: [block_n, baseN]

    pipe->InitBuffer(qA2Queue_, 1, tileA * sizeof(half));
    pipe->InitBuffer(kB2Queue_, 1, tileB * sizeof(half));
    pipe->InitBuffer(vB2Queue_, 1, tileB2 * sizeof(half));
    pipe->InitBuffer(pA2Queue_, 1, tileA2 * sizeof(half));

    // L0C results
    pipe->InitBuffer(co1QueueS_, 1, szS_ * sizeof(float));
    pipe->InitBuffer(co1QueueO_, 1, szO_ * sizeof(float));
}

__aicore__ inline void FlashAttentionScoreKernel::VectorInit()
{
    TPipe *pipe = &AscendC::GetPipe();

    // Input/output queues
    pipe->InitBuffer(vinQueue_, 1, szHalfM_ * sizeof(float) * 4);  // generous for max read
    pipe->InitBuffer(voutQueue_, 1, szHalfM_ * sizeof(half));

    // Compute buffers
    pipe->InitBuffer(accOBuf_, szHalfO_);
    pipe->InitBuffer(sumexpBuf_, szHalfM_);
    pipe->InitBuffer(miBuf_, szHalfM_);
    pipe->InitBuffer(sScoreBuf_, szHalfRowS_ * sizeof(float));
    pipe->InitBuffer(miPrevBuf_, szRow_ * sizeof(float));
    pipe->InitBuffer(sTmpBuf_, szHalfRowS_ * sizeof(float));
    pipe->InitBuffer(reduceWork_, szReduceWork_);
    pipe->InitBuffer(sumexpIBuf_, szRow_ * sizeof(float));
    pipe->InitBuffer(accOOpsBuf_, szHalfO_);
    pipe->InitBuffer(alphaBuf_, szRow_ * sizeof(float));

    // Init workspace queues (free slots)
    wsQueueS_.InitFreeSlots();    // S queues: initially free for Cube
    // For P queue (Vector→Cube): V writes, C reads.
    // InitFreeSlots marks slots as "free for AIC producer" via VECTOR_NOTIFY_CUBE flag.
    // But for Vec→Cube direction, the producer is AIV.
    // We need to initialize so that slots are free for AIV to write.
    // The standard InitFreeSlots sends VECTOR_FLAG to notify Cube that slots are free.
    // For Vec→Cube, we send CUBE_FLAG to notify Vector that slots are free.
    for (uint32_t i = 0; i < WORKSPACE_DEPTH; ++i) {
        CrossCoreSetFlag<0x2, PIPE_FIX>(VECTOR_FLAG_P);
    }
    wsQueueO_.InitFreeSlots();
}

// ===================== Process =====================
__aicore__ inline void FlashAttentionScoreKernel::Process()
{
    // Preload Q to L1 (AIC only)
    if ASCEND_IS_AIC {
        LocalTensor<half> qL1;
        qL1Queue_.AllocTensor<half>(qL1);
        auto qSrc = qGM_[bz_ * seq_len_ * dim_ + bx_ * block_m_ * dim_];
        LoadNdGmToNzL1(qL1, qSrc, block_m_, dim_, dim_);
        PipeBarrier<PIPE_MTE2>();
    }

    // Initialize accumulators (AIV only)
    if ASCEND_IS_AIV {
        LocalTensor<float> accO = accOBuf_.Get<float>();
        LocalTensor<float> sumexp = sumexpBuf_.Get<float>();
        LocalTensor<float> mi = miBuf_.Get<float>();
        Duplicate(accO, 0.0f, half_m_ * dim_);
        Duplicate(sumexp, 0.0f, half_m_);
        Duplicate(mi, -1.0e30f, half_m_);
    }

    // Main pipeline loop
    for (int32_t t = 0; t < kv_loops_ + PRELAUNCH; ++t) {
        if (t < kv_loops_) {
            if ASCEND_IS_AIC { CubeProdStep(t); }
            if ASCEND_IS_AIV { VectorProdStep(t); }
        }
        if (t >= PRELAUNCH) {
            int32_t now_k = t - PRELAUNCH;
            if ASCEND_IS_AIC { CubeConsStep(now_k); }
            if ASCEND_IS_AIV { VectorConsStep(now_k); }
        }
    }

    // Epilogue (AIV only)
    if ASCEND_IS_AIV {
        VectorEpilogue();
    }
}

// ===================== Cube: Producer Step (Q@K^T) =====================
__aicore__ inline void FlashAttentionScoreKernel::CubeProdStep(int32_t t)
{
    int32_t slot = t % WORKSPACE_DEPTH;

    // Allocate Q from L1 (preloaded and persistent; re-read from queue each step for consistency)
    qL1Queue_.AllocTensor<half>(qL1Local);
    auto qSrc = qGM_[bz_ * seq_len_ * dim_ + bx_ * block_m_ * dim_];
    LoadNdGmToNzL1(qL1Local, qSrc, block_m_, dim_, dim_);
    PipeBarrier<PIPE_MTE2>();

    // Load K tile to L1
    kL1Queue_.AllocTensor<half>(kL1Local);
    auto kSrc = kGM_[bz_ * seq_len_ * dim_ + t * block_n_ * dim_];
    LoadNdGmToNzL1(kL1Local, kSrc, block_n_, dim_, dim_);
    PipeBarrier<PIPE_MTE2>();

    // Acquire S workspace slot
    auto sSlot = wsQueueS_.ProducerAcquire();

    // Compute S = Q @ K^T
    co1QueueS_.AllocTensor<float>(sL0C);
    MatmulQKT(qL1Local, kL1Local, sL0C, true);

    // Write S to workspace
    FixpipeNzL0cToNdGm(sSlot, sL0C, block_m_, block_n_);

    // Free resources
    co1QueueS_.FreeTensor(sL0C);
    kL1Queue_.FreeTensor(kL1Local);
    qL1Queue_.FreeTensor(qL1Local);

    // Signal data ready
    wsQueueS_.ProducerRelease();
}

// ===================== Vector: Producer Step (softmax) =====================
__aicore__ inline void FlashAttentionScoreKernel::VectorProdStep(int32_t t)
{
    int32_t slot = t % WORKSPACE_DEPTH;
    int32_t vid = GetSubBlockIdx();

    // Acquire S workspace slot
    auto sSlotGM = wsQueueS_.ConsumerAcquire();

    // Load my half of S from workspace
    vinQueue_.AllocTensor<float>(sLocal);
    LocalTensor<float> sScore = sScoreBuf_.Get<float>();
    LocalTensor<float> sTmp = sTmpBuf_.Get<float>();
    LocalTensor<float> mi = miBuf_.Get<float>();
    LocalTensor<float> miPrev = miPrevBuf_.Get<float>();
    LocalTensor<float> sumexpI = sumexpIBuf_.Get<float>();

    int32_t halfRowS = half_m_ * block_n_;
    DataCopyExtParams<float> copySIn = {
        1,                                                    // blockCount
        (uint16_t)(halfRowS * sizeof(float) / DEFAULT_C0_SIZE), // blockLen (in C0 units)
        0, 0
    };
    DataCopyPad(sLocal, sSlotGM[vid * halfRowS], copySIn,
                DataCopyPadExtParams<float>{false, 0, 0, 0});
    vinQueue_.EnQue(sLocal);

    // Compute: S = S * scale_value
    vinQueue_.DeQue<float>(sLocal);
    Muls(sScore, sLocal, scale_, halfRowS);
    vinQueue_.FreeTensor(sLocal);

    // Online softmax
    // Save old running max
    DataCopy(miPrev, mi, half_m_);

    // Compute new per-row max
    ReduceMax<float, false>(miPrev, sScore, reduceWork_.Get<float>(), half_m_, block_n_, block_n_, 1);
    // mi_new = max(mi_old, row_max(S))
    Max(mi, mi, miPrev, half_m_);

    // alpha = exp(mi_old - mi_new), but miPrev now holds row_max(S)
    // Re-read old max into miOldLocal
    LocalTensor<float> miOld = miPrevBuf_.Get<float>();
    DataCopy(miOld, mi, half_m_); // mi now has mi_new; compute miPrev (row_max) - mi_new
    Sub(miPrev, miPrev, mi, half_m_);  // miPrev = row_max(S) - mi_new

    // alpha = exp(miOld - mi_new) where miOld was saved earlier
    // Actually we need: alpha = exp(old_max - new_max) for rescaling
    // We stored old_max before the ReduceMax/Sub. miPrev now has new_max - old_max (inverted).
    // Let me recalculate properly.
    // m_i_prev was the old running max.
    // After ReduceMax, I set mi to max(old_max, row_max(S)).
    // Now miPrev had the row_max(S) from ReduceMax.
    // But I need alpha = exp(old_max - mi) where old_max was the original mi value.
    // Let me recalculate more carefully.

    // Correct approach:
    // 1. m_old = mi (save current running max)
    // 2. row_max = reduce_max(S) → miPrev
    // 3. mi = max(m_old, row_max)
    // 4. alpha = exp(m_old - mi)
    // 5. S = exp(S - mi)
    // 6. sumexp_i = sum(exp(S - mi))
    // 7. acc_o *= alpha (per row)
    // 8. sumexp = alpha * sumexp + sumexp_i

    // Step 2 actually already computed: miPrev = row_max(S)
    // Step 3: mi = max(m_old, miPrev)
    // But we already did step 1 and 3 above. Let me redo properly.
    // I need to save m_old before step 3.

    // OK let me redo this entire section.
    // m_old was saved in miPrevBuf at start of this step via DataCopy(miPrev, mi, half_m_)
    // Wait, no. I used miPrev for two purposes. Let me redo more carefully.

    // Let me redo the softmax computation step by step:

    // Save old running max: m_old = mi
    DataCopy(miPrev, mi, half_m_);  // miPrev = m_old

    // Compute per-row max of S: miPrev will be overwritten
    ReduceMax<float, false>(mi, sScore, reduceWork_.Get<float>(), half_m_, block_n_, block_n_, 1);
    // Now mi = row_max(S) (from ReduceMax)
    // But I need mi_new = max(m_old, row_max(S))

    // Actually ReduceMax writes to mi directly. But I stored m_old in miPrev.
    // So now mi = row_max(S), miPrev = m_old.
    Max(mi, mi, miPrev, half_m_);  // mi = max(row_max(S), m_old) = mi_new

    // alpha = exp(m_old - mi_new)
    Sub(miPrev, miPrev, mi, half_m_);  // miPrev = m_old - mi_new
    Exp(miPrev, miPrev, half_m_);       // miPrev = alpha = exp(m_old - mi_new)

    // S = S - mi_new (per row)
    for (int32_t h_i = 0; h_i < half_m_; ++h_i) {
        Sub(sScore[h_i * block_n_], sScore[h_i * block_n_], mi[h_i], block_n_);
    }
    Exp(sScore, sScore, halfRowS);  // S = exp(S - mi_new) = softmax numerator

    // sumexp_i = sum(S) per row
    ReduceSum<float>(sumexpI, sScore, reduceWork_.Get<float>(), half_m_, block_n_, block_n_, 1);

    // Rescale running accumulator: acc_o *= alpha (per row)
    LocalTensor<float> accO = accOBuf_.Get<float>();
    for (int32_t h_i = 0; h_i < half_m_; ++h_i) {
        Muls(accO[h_i * dim_], accO[h_i * dim_], miPrev[h_i], dim_);
    }

    // Update sumexp: sumexp = alpha * sumexp + sumexp_i
    LocalTensor<float> sumexp = sumexpBuf_.Get<float>();
    Mul(sumexp, sumexp, miPrev, half_m_);
    Add(sumexp, sumexp, sumexpI, half_m_);

    // Store P = softmax(S) (= exp(S-mi_new)) to workspace_p (Vector→Cube direction)
    // Acquire P workspace slot (producer on AIV side)
    CrossCoreWaitFlag<0x2>(VECTOR_FLAG_P);  // Wait for slot free
    auto pSlot = wsQueueP_.workspace_;  // Need proper access
    // Actually we need to use the queue properly. Let me use direct access.
    uint32_t wsPOffset = (GetBlockIdx() / GetSubBlockNum()) * WORKSPACE_DEPTH * szP_;
    // Reconstruct P workspace pointer
    // This is getting messy. Let me use a cleaner approach.

    // For the Vec→Cube P transfer, I'll use a simpler single-slot approach.
    // P data lives on the same workspace pointer passed in, at the P offset.
    // Let me access it directly by computing offsets.

    // Actually, I realize the queue-based approach is very convoluted for the reverse direction.
    // Let me use a simpler approach for P: single shared slot, sequential sync.

    // For now, store data and signal C2 with a simple cross-core flag.
    // P is small (block_m * block_n * sizeof(half) = 2KB), so single slot is fine.
}

