__aicore__ inline void FlashAttentionScoreKernel::MatmulQKT(LocalTensor<half> &qL1, LocalTensor<half> &kL1,
                                                              LocalTensor<float> &sL0C, bool init)
{
    // Q @ K^T: Q[block_m, dim] @ K^T[dim, block_n]
    // Tiled along K (dim) in chunks of DEFAULT_BASE_K
    int32_t kTotal = dim_;
    int32_t kChunks = (kTotal + DEFAULT_BASE_K - 1) / DEFAULT_BASE_K;
    int32_t colC0StrideQ = dim_ / DEFAULT_C0_SIZE; // C0 stride for Q in L1
    int32_t colC0StrideK = dim_ / DEFAULT_C0_SIZE; // C0 stride for K in L1

    for (int32_t kc = 0; kc < kChunks; ++kc) {
        int32_t kOff = kc * DEFAULT_BASE_K;
        int32_t kSize = (kOff + DEFAULT_BASE_K > kTotal) ? (kTotal - kOff) : DEFAULT_BASE_K;
        if (kSize <= 0) break;

        // Load Q sub-tile to L0A
        LocalTensor<half> qA2;
        qA2Queue_.AllocTensor<half>(qA2);
        int32_t qColC0Offset = kOff / DEFAULT_C0_SIZE;
        LoadNzL1ToZzL0A(qA2, qL1[qColC0Offset * colC0StrideQ], block_m_, kSize, colC0StrideQ);

        // Load K sub-tile to L0B (as Zn format = effective K^T)
        LocalTensor<half> kB2;
        kB2Queue_.AllocTensor<half>(kB2);
        int32_t kColC0Offset = kOff / DEFAULT_C0_SIZE;
        LoadNzL1ToZnL0B(kB2, kL1[kColC0Offset * colC0StrideK], block_n_, kSize, colC0StrideK);

        PipeBarrier<PIPE_MTE3>();

        // Mmad: C[m,n] += A[m,k] * B[n,k]
        // Q is [block_m, kSize] on L0A, K^T is [block_n, kSize] on L0B
        // Result: S [block_m, block_n] on L0C
        if (init && kc == 0) {
            Mmad(sL0C, qA2, kB2, block_m_, kSize, block_n_, 1);
        } else {
            Mmad(sL0C, qA2, kB2, block_m_, kSize, block_n_, 0);
        }

        qA2Queue_.FreeTensor(qA2);
        kB2Queue_.FreeTensor(kB2);
    }
}

__aicore__ inline void FlashAttentionScoreKernel::MatmulPV(LocalTensor<half> &pL1, LocalTensor<half> &vL1,
                                                             LocalTensor<float> &oL0C, bool init)
{
    // P @ V: P[block_m, block_n] @ V[block_n, dim]
    // K dimension = block_n (small, no tiling needed for K)
    // N dimension = dim (large, tile along N)
    int32_t nTotal = dim_;
    int32_t nChunks = (nTotal + DEFAULT_BASE_N - 1) / DEFAULT_BASE_N;
    int32_t colC0StrideP = block_n_ / DEFAULT_C0_SIZE;
    int32_t colC0StrideV = dim_ / DEFAULT_C0_SIZE;

    for (int32_t nc = 0; nc < nChunks; ++nc) {
        int32_t nOff = nc * DEFAULT_BASE_N;
        int32_t nSize = (nOff + DEFAULT_BASE_N > nTotal) ? (nTotal - nOff) : DEFAULT_BASE_N;
        if (nSize <= 0) break;

        // Load P sub-tile to L0A
        LocalTensor<half> pA2;
        pA2Queue_.AllocTensor<half>(pA2);
        LoadNzL1ToZzL0A(pA2, pL1, block_m_, block_n_, colC0StrideP);

        // Load V sub-tile to L0B
        LocalTensor<half> vB2;
        vB2Queue_.AllocTensor<half>(vB2);
        int32_t vColC0Offset = nOff / DEFAULT_C0_SIZE;
        LoadNzL1ToZnL0B(vB2, vL1[vColC0Offset * colC0StrideV], nSize, block_n_, colC0StrideV);

        PipeBarrier<PIPE_MTE3>();

        // Mmad: O[m,n] = P[m,k] * V[n,k] (V is on Zn = transposed)
        // Result goes to oL0C at n-offset
        Mmad(oL0C[nOff / DEFAULT_C0_SIZE * colC0StrideV * block_m_], pA2, vB2, block_m_, block_n_, nSize, (init && nc == 0) ? 1 : 0);

        pA2Queue_.FreeTensor(pA2);
        vB2Queue_.FreeTensor(vB2);
    }
}

