#ifndef FLASH_ATTENTION_SCORE_KERNEL_H
#define FLASH_ATTENTION_SCORE_KERNEL_H

#include "kernel_operator.h"

using namespace AscendC;
constexpr int32_t C0_SIZE = DEFAULT_C0_SIZE;

// Cube tiling tile sizes
constexpr int32_t CUBE_BASE_K = 128;
constexpr int32_t CUBE_BASE_N = 128;

// Cross-core flag IDs for sequential sync
#define FA_FLAG_S_READY   0x08
#define FA_FLAG_P_READY   0x09
#define FA_FLAG_O_READY   0x0A

// Tiling data passed from host
#pragma pack(push, 8)
struct FlashAttentionTiling {
    int32_t batch;
    int32_t seq_len;
    int32_t dim;
    int32_t block_m;
    int32_t block_n;
    int32_t kv_loops;
    int32_t m_blocks;
    int32_t total_cores;
    float   scale_value;
};
#pragma pack(pop)

// Copy tiling from GM
__aicore__ inline void faCopyTiling(FlashAttentionTiling *t, GM_ADDR gm)
{
    auto src = reinterpret_cast<__gm__ int32_t *>(gm);
    auto dst = reinterpret_cast<int32_t *>(t);
    for (uint32_t i = 0; i < sizeof(FlashAttentionTiling) / sizeof(int32_t); ++i)
        dst[i] = src[i];
}

// ============ Cube-side Matmul helpers ============
// Load GM(ND) to L1(Nz)
template<typename T>
__aicore__ inline void faGmToL1(const LocalTensor<T> &dst, const GlobalTensor<T> &src,
                                uint32_t m, uint32_t n, uint32_t ld)
{
    Nd2NzParams p; p.ndNum = 1; p.nValue = m; p.dValue = n;
    p.srcNdMatrixStride = 0; p.srcDValue = ld;
    p.dstNzC0Stride = m; p.dstNzNStride = 1; p.dstNzMatrixStride = 0;
    DataCopy(dst, src, p);
}

// Load L1(Nz) to L0A(Zz)
template<typename T>
__aicore__ inline void faL1ToL0A(const LocalTensor<T> &dst, const LocalTensor<T> &src,
                                 uint32_t m, uint32_t k, uint32_t colC0Stride)
{
    LoadData3DParamsV2<T> p;
    p.l1H = 1; p.l1W = colC0Stride;
    p.channelSize = k; p.kExtension = k; p.mExtension = m;
    p.strideH = 1; p.strideW = 1;
    p.filterH = 1; p.filterW = 1;
    p.dilationFilterH = 1; p.dilationFilterW = 1;
    LoadData(dst, src, p);
}

// Load L1(Nz) to L0B(Zn) — Nz→Zn provides transposed view
template<typename T>
__aicore__ inline void faL1ToL0B(const LocalTensor<T> &dst, const LocalTensor<T> &src,
                                 uint32_t n, uint32_t k, uint32_t colC0Stride)
{
    LoadData3DParamsV2<T> p;
    p.l1H = 1; p.l1W = colC0Stride;
    p.channelSize = n; p.kExtension = n; p.mExtension = k;
    p.strideH = 1; p.strideW = 1;
    p.filterH = 1; p.filterW = 1;
    p.dilationFilterH = 1; p.dilationFilterW = 1;
    LoadData(dst, src, p);
}

// Fixpipe L0C(Nz) to GM(ND)
template<typename T>
__aicore__ inline void faL0cToGm(const GlobalTensor<T> &dst, const LocalTensor<T> &src,
                                 uint32_t m, uint32_t n)
{
    FixpipeParamsV220 p;
    p.nSize = n; p.mSize = m;
    p.srcStride = m; p.dstStride = n;
    p.ndNum = 1; p.srcNdStride = 0; p.dstNdStride = 0;
    Fixpipe(dst, src, p);
}

// Default DataCopy for GM<->UB
template<typename T>
__aicore__ inline void faGmToUbPad(LocalTensor<T> &local, const GlobalTensor<T> &global,
                                   uint32_t elems)
{
    DataCopyPadExtParams<T> pad = {false, 0, 0, 0};
    DataCopyExtParams<T> ext = {1, (uint16_t)(elems * sizeof(T) / C0_SIZE), 0, 0};
    DataCopyPad(local, global, ext, pad);
}

template<typename T>
__aicore__ inline void faUbToGmPad(GlobalTensor<T> &global, const LocalTensor<T> &local,
                                   uint32_t elems)
{
    DataCopyExtParams<T> ext = {1, (uint16_t)(elems * sizeof(T) / C0_SIZE), 0, 0};
    DataCopyPad(global, local, ext);
}

// ============ Main Kernel Class ============
class FlashAttentionScoreKernel {
public:
    __aicore__ inline void Init(GM_ADDR q, GM_ADDR k, GM_ADDR v, GM_ADDR output,
                                GM_ADDR ws_s, GM_ADDR ws_p, GM_ADDR ws_o,
                                GM_ADDR tilingGM, TPipe *pipe);
    __aicore__ inline void Process();

private:
    FlashAttentionTiling t_;
    int32_t bx_, bz_;     // seq-block and batch indices for this core
    int32_t halfM_;       // block_m / 2 (per-AIV sub-block)

    // GM tensors (raw addresses for offset computation)
    __gm__ half *qBase_, *kBase_, *vBase_, *oBase_;
    __gm__ float *wsSBase_, *wsOBase_;
    __gm__ half *wsPBase_;

    // --- AIC (Cube) buffers ---
    TQue<TPosition::A1, 1> qL1Q_;    // Q [block_m, dim] — persistent
    TQue<TPosition::B1, 1> kL1Q_;    // K [block_n, dim] — per step
    TQue<TPosition::A1, 1> pL1Q_;    // P [block_m, block_n] — per step
    TQue<TPosition::B1, 1> vL1Q_;    // V [block_n, dim] — per step

    TQue<TPosition::A2, 1> qA2Q_;    // L0A tiles
    TQue<TPosition::B2, 1> kB2Q_;    // L0B tiles
    TQue<TPosition::A2, 1> pA2Q_;
    TQue<TPosition::B2, 1> vB2Q_;

    TQue<TPosition::CO1, 1> co1SQ_;  // S [block_m, block_n] float
    TQue<TPosition::CO1, 1> co1OQ_;  // O_tmp [block_m, dim] float

    // --- AIV (Vector) buffers ---
    TQue<TPosition::VECIN, 1> viQ_;   // Generic input
    TQue<TPosition::VECOUT, 1> voQ_;  // Generic output

    TBuf<TPosition::VECCALC> accOBuf_;     // [halfM, dim] float — running O
    TBuf<TPosition::VECCALC> sumexpBuf_;   // [halfM] float — running sumexp
    TBuf<TPosition::VECCALC> miBuf_;       // [halfM] float — running max
    TBuf<TPosition::VECCALC> scoreBuf_;    // [halfM, block_n] float — S*scale
    TBuf<TPosition::VECCALC> miOldBuf_;    // [halfM] float — saved old max
    TBuf<TPosition::VECCALC> rwBuf_;       // Reduce workspace
    TBuf<TPosition::VECCALC> sumexpIBuf_;  // [halfM] float — per-step sumexp
    TBuf<TPosition::VECCALC> oTmpBuf_;     // [halfM, dim] float — O_tmp from consumer
    TPipe *pipe_;

    // Pipeline steps
    __aicore__ inline void AIC_ProdStep(int32_t t);
    __aicore__ inline void AIV_ProdStep(int32_t t);
    __aicore__ inline void AIC_ConsStep(int32_t nowK);
    __aicore__ inline void AIV_ConsStep(int32_t nowK);
    __aicore__ inline void AIV_Epilogue();
};

// ================================================================
// Init
// ================================================================
__aicore__ inline void FlashAttentionScoreKernel::Init(
    GM_ADDR q, GM_ADDR k, GM_ADDR v, GM_ADDR output,
    GM_ADDR ws_s, GM_ADDR ws_p, GM_ADDR ws_o,
    GM_ADDR tilingGM, TPipe *pipe)
{
    pipe_ = pipe;
    faCopyTiling(&t_, tilingGM);

    int32_t coreIdx = GetBlockIdx() / GetSubBlockNum();
    bz_ = coreIdx / t_.m_blocks;
    bx_ = coreIdx % t_.m_blocks;
    halfM_ = t_.block_m / 2;

    qBase_ = reinterpret_cast<__gm__ half *>(q);
    kBase_ = reinterpret_cast<__gm__ half *>(k);
    vBase_ = reinterpret_cast<__gm__ half *>(v);
    oBase_ = reinterpret_cast<__gm__ half *>(output);
    wsSBase_ = reinterpret_cast<__gm__ float *>(ws_s);
    wsPBase_ = reinterpret_cast<__gm__ half *>(ws_p);
    wsOBase_ = reinterpret_cast<__gm__ float *>(ws_o);

    int32_t szQ = t_.block_m * t_.dim;
    int32_t szK = t_.block_n * t_.dim;
    int32_t szP = t_.block_m * t_.block_n;
    int32_t szS = t_.block_m * t_.block_n;
    int32_t szO = t_.block_m * t_.dim;
    int32_t halfSz = halfM_ * t_.dim;
    int32_t halfRS = halfM_ * t_.block_n;
    int32_t rowSz = halfM_;
    int32_t rwSz = halfM_ * t_.block_n * sizeof(float) * 3 / 4;

    if ASCEND_IS_AIC {
        pipe->InitBuffer(qL1Q_, 1, szQ * sizeof(half));
        pipe->InitBuffer(kL1Q_, 1, szK * sizeof(half));
        pipe->InitBuffer(pL1Q_, 1, szP * sizeof(half));
        pipe->InitBuffer(vL1Q_, 1, szK * sizeof(half));

        pipe->InitBuffer(qA2Q_, 1, t_.block_m * CUBE_BASE_K * sizeof(half));
        pipe->InitBuffer(kB2Q_, 1, t_.block_n * CUBE_BASE_K * sizeof(half));
        pipe->InitBuffer(pA2Q_, 1, szP * sizeof(half));
        pipe->InitBuffer(vB2Q_, 1, t_.block_n * CUBE_BASE_N * sizeof(half));

        pipe->InitBuffer(co1SQ_, 1, szS * sizeof(float));
        pipe->InitBuffer(co1OQ_, 1, szO * sizeof(float));
    }

    if ASCEND_IS_AIV {
        pipe->InitBuffer(viQ_, 1, halfSz * sizeof(float) * 2);  // generous
        pipe->InitBuffer(voQ_, 1, halfSz * sizeof(half));

        pipe->InitBuffer(accOBuf_, halfSz * sizeof(float));
        pipe->InitBuffer(sumexpBuf_, rowSz * sizeof(float));
        pipe->InitBuffer(miBuf_, rowSz * sizeof(float));
        pipe->InitBuffer(scoreBuf_, halfRS * sizeof(float));
        pipe->InitBuffer(miOldBuf_, rowSz * sizeof(float));
        pipe->InitBuffer(rwBuf_, rwSz);
        pipe->InitBuffer(sumexpIBuf_, rowSz * sizeof(float));
        pipe->InitBuffer(oTmpBuf_, halfSz * sizeof(float));
    }
}

// ================================================================
// Process — main loop
// ================================================================
__aicore__ inline void FlashAttentionScoreKernel::Process()
{
    int32_t totalIters = t_.kv_loops;

    // Preload Q to L1 (AIC only, persistent)
    if ASCEND_IS_AIC {
        LocalTensor<half> qL1;
        qL1Q_.AllocTensor<half>(qL1);
        GlobalTensor<half> qGm;
        qGm.SetGlobalBuffer(qBase_, t_.batch * t_.seq_len * t_.dim);
        int32_t qOff = bz_ * t_.seq_len * t_.dim + bx_ * t_.block_m * t_.dim;
        faGmToL1(qL1, qGm[qOff], t_.block_m, t_.dim, t_.dim);
    }

    // Init accumulators (AIV only)
    if ASCEND_IS_AIV {
        LocalTensor<float> o    = accOBuf_.Get<float>();
        LocalTensor<float> se   = sumexpBuf_.Get<float>();
        LocalTensor<float> mi   = miBuf_.Get<float>();
        Duplicate(o, 0.0f, halfM_ * t_.dim);
        Duplicate(se, 0.0f, halfM_);
        Duplicate(mi, -1.0e30f, halfM_);
    }

    // Main loop: each kv step involves 4 sub-steps with sequential sync
    for (int32_t t = 0; t < totalIters; ++t) {
        if ASCEND_IS_AIC { AIC_ProdStep(t); }
        if ASCEND_IS_AIV { AIV_ProdStep(t); }

        if ASCEND_IS_AIC { AIC_ConsStep(t); }
        if ASCEND_IS_AIV { AIV_ConsStep(t); }
    }

    // Epilogue
    if ASCEND_IS_AIV { AIV_Epilogue(); }
}

// ================================================================
// AIC_ProdStep: Q @ K^T → S, write to ws_s, signal AIV
// ================================================================
__aicore__ inline void FlashAttentionScoreKernel::AIC_ProdStep(int32_t t)
{
    // Load K[t] to L1
    LocalTensor<half> kL1;
    kL1Q_.AllocTensor<half>(kL1);
    GlobalTensor<half> kGm;
    kGm.SetGlobalBuffer(kBase_, t_.batch * t_.seq_len * t_.dim);
    int32_t kOff = bz_ * t_.seq_len * t_.dim + t * t_.block_n * t_.dim;
    faGmToL1(kL1, kGm[kOff], t_.block_n, t_.dim, t_.dim);
    PipeBarrier<PIPE_MTE2>();

    // Get Q from L1 (persistent)
    LocalTensor<half> qL1;
    qL1Q_.AllocTensor<half>(qL1);

    // S = Q @ K^T on L0C
    LocalTensor<float> sL0C;
    co1SQ_.AllocTensor<float>(sL0C);

    // Matmul Q[block_m, dim] @ K^T[dim, block_n]
    int32_t colC0Q = t_.dim / C0_SIZE;
    int32_t colC0K = t_.dim / C0_SIZE;
    int32_t kChunks = (t_.dim + CUBE_BASE_K - 1) / CUBE_BASE_K;

    for (int32_t kc = 0; kc < kChunks; ++kc) {
        int32_t kOff2 = kc * CUBE_BASE_K;
        int32_t kSz = (kOff2 + CUBE_BASE_K > t_.dim) ? (t_.dim - kOff2) : CUBE_BASE_K;
        if (kSz <= 0) break;

        LocalTensor<half> qA2;
        qA2Q_.AllocTensor<half>(qA2);
        faL1ToL0A(qA2, qL1[kOff2 / C0_SIZE * colC0Q], t_.block_m, kSz, colC0Q);

        LocalTensor<half> kB2;
        kB2Q_.AllocTensor<half>(kB2);
        faL1ToL0B(kB2, kL1[kOff2 / C0_SIZE * colC0K], t_.block_n, kSz, colC0K);

        PipeBarrier<PIPE_MTE3>();
        Mmad(sL0C, qA2, kB2, t_.block_m, kSz, t_.block_n, (kc == 0) ? 1 : 0);

        qA2Q_.FreeTensor(qA2);
        kB2Q_.FreeTensor(kB2);
    }

    // Fixpipe S to ws_s
    int32_t coreIdx = GetBlockIdx() / GetSubBlockNum();
    GlobalTensor<float> wsS;
    wsS.SetGlobalBuffer(wsSBase_, coreIdx * t_.block_m * t_.block_n);
    faL0cToGm(wsS, sL0C, t_.block_m, t_.block_n);

    co1SQ_.FreeTensor(sL0C);
    qL1Q_.FreeTensor(qL1);
    kL1Q_.FreeTensor(kL1);

    // Signal AIV: S is ready
    CrossCoreSetFlag<0x2, PIPE_FIX>(FA_FLAG_S_READY);

    // Wait for AIV: P is ready (after AIV does softmax)
    CrossCoreWaitFlag<0x2>(FA_FLAG_P_READY);
}

// ================================================================
// AIV_ProdStep: Read S, softmax, write P, signal AIC
// ================================================================
__aicore__ inline void FlashAttentionScoreKernel::AIV_ProdStep(int32_t t)
{
    int32_t vid = GetSubBlockIdx();
    int32_t coreIdx = GetBlockIdx() / GetSubBlockNum();

    // Wait for S to be ready
    CrossCoreWaitFlag<0x2>(FA_FLAG_S_READY);

    // Read my half of S from ws_s: [vid * halfM : vid * halfM + halfM, :]
    int32_t halfRowS = halfM_ * t_.block_n;
    int32_t sOffset = vid * halfRowS;

    LocalTensor<float> sLocal;
    viQ_.AllocTensor<float>(sLocal);
    GlobalTensor<float> wsS;
    wsS.SetGlobalBuffer(wsSBase_, coreIdx * t_.block_m * t_.block_n);
    faGmToUbPad(sLocal, wsS[sOffset], halfRowS);
    viQ_.EnQue(sLocal);

    LocalTensor<float> score = scoreBuf_.Get<float>();
    LocalTensor<float> mi    = miBuf_.Get<float>();
    LocalTensor<float> miOld = miOldBuf_.Get<float>();
    LocalTensor<float> rw    = rwBuf_.Get<float>();
    LocalTensor<float> seI   = sumexpIBuf_.Get<float>();

    viQ_.DeQue<float>(sLocal);

    // S *= scale
    Muls(score, sLocal, t_.scale_value, halfRowS);
    viQ_.FreeTensor(sLocal);

    // Online softmax
    // 1. Save old max
    DataCopy(miOld, mi, halfM_);

    // 2. Compute per-row max of S
    ReduceMax<float, false>(mi, score, rw, halfM_, t_.block_n, t_.block_n, 1);

    // 3. mi = max(old_max, row_max(S))
    Max(mi, mi, miOld, halfM_);

    // 4. alpha = exp(old_max - mi) — stored in miOld
    Sub(miOld, miOld, mi, halfM_);
    Exp(miOld, miOld, halfM_);

    // 5. S = exp(S - mi)
    for (int32_t h = 0; h < halfM_; ++h) {
        Subs(score[h * t_.block_n], score[h * t_.block_n], mi[h], t_.block_n);
    }
    Exp(score, score, halfRowS);

    // 6. sumexp_i = per-row sum(S)
    ReduceSum<float>(seI, score, rw, halfM_, t_.block_n, t_.block_n, 1);

    // 7. Rescale running O: acc_o *= alpha
    LocalTensor<float> o = accOBuf_.Get<float>();
    for (int32_t h = 0; h < halfM_; ++h) {
        Muls(o[h * t_.dim], o[h * t_.dim], miOld[h], t_.dim);
    }

    // 8. Update running sumexp: sumexp = alpha * sumexp + sumexp_i
    LocalTensor<float> se = sumexpBuf_.Get<float>();
    Mul(se, se, miOld, halfM_);
    Add(se, se, seI, halfM_);

    // 9. Write P = softmax(S) to ws_p (cast to fp16)
    // P lives in the P workspace slot at [coreIdx * block_m * block_n]
    int32_t pOffset = coreIdx * t_.block_m * t_.block_n + vid * halfRowS;
    GlobalTensor<half> wsP;
    wsP.SetGlobalBuffer(wsPBase_, coreIdx * t_.block_m * t_.block_n + t_.block_m * t_.block_n);
    LocalTensor<half> pHalf = voQ_.AllocTensor<half>();
    Cast(pHalf, score, RoundMode::CAST_ROUND, halfRowS);
    faUbToGmPad(wsP, pHalf, halfRowS);
    voQ_.FreeTensor(pHalf);

    // Signal AIC: P is ready
    CrossCoreSetFlag<0x2, PIPE_MTE2>(FA_FLAG_P_READY);

    // Wait for O_tmp to be ready (from C2)
    CrossCoreWaitFlag<0x2>(FA_FLAG_O_READY);
}

// ================================================================
// AIC_ConsStep: P @ V → O_tmp, write to ws_o, signal AIV
// ================================================================
__aicore__ inline void FlashAttentionScoreKernel::AIC_ConsStep(int32_t t)
{
    int32_t coreIdx = GetBlockIdx() / GetSubBlockNum();

    // Load P from ws_p to L1
    LocalTensor<half> pL1;
    pL1Q_.AllocTensor<half>(pL1);
    GlobalTensor<half> wsP;
    wsP.SetGlobalBuffer(wsPBase_, coreIdx * t_.block_m * t_.block_n + t_.block_m * t_.block_n);
    faGmToL1(pL1, wsP, t_.block_m, t_.block_n, t_.block_n);
    PipeBarrier<PIPE_MTE2>();

    // Load V[t] to L1
    LocalTensor<half> vL1;
    vL1Q_.AllocTensor<half>(vL1);
    GlobalTensor<half> vGm;
    vGm.SetGlobalBuffer(vBase_, t_.batch * t_.seq_len * t_.dim);
    int32_t vOff = bz_ * t_.seq_len * t_.dim + t * t_.block_n * t_.dim;
    faGmToL1(vL1, vGm[vOff], t_.block_n, t_.dim, t_.dim);
    PipeBarrier<PIPE_MTE2>();

    // O_tmp = P @ V on L0C
    LocalTensor<float> oL0C;
    co1OQ_.AllocTensor<float>(oL0C);

    int32_t colC0P = t_.block_n / C0_SIZE;
    int32_t colC0V = t_.dim / C0_SIZE;

    // Tile along N (dim) in chunks of CUBE_BASE_N for Fixpipe-friendly output
    int32_t nChunks = (t_.dim + CUBE_BASE_N - 1) / CUBE_BASE_N;
    for (int32_t nc = 0; nc < nChunks; ++nc) {
        int32_t nOff = nc * CUBE_BASE_N;
        int32_t nSz = (nOff + CUBE_BASE_N > t_.dim) ? (t_.dim - nOff) : CUBE_BASE_N;
        if (nSz <= 0) break;

        LocalTensor<half> pA2;
        pA2Q_.AllocTensor<half>(pA2);
        faL1ToL0A(pA2, pL1, t_.block_m, t_.block_n, colC0P);

        LocalTensor<half> vB2;
        vB2Q_.AllocTensor<half>(vB2);
        faL1ToL0B(vB2, vL1[nOff / C0_SIZE * colC0V], nSz, t_.block_n, colC0V);

        PipeBarrier<PIPE_MTE3>();
        // Result at [block_m, nOff:nOff+nSz] in L0C Nz layout
        int32_t oC0Off = nOff / C0_SIZE * t_.block_m;
        Mmad(oL0C[oC0Off], pA2, vB2, t_.block_m, t_.block_n, nSz, (nc == 0) ? 1 : 0);

        pA2Q_.FreeTensor(pA2);
        vB2Q_.FreeTensor(vB2);
    }

    // Fixpipe O_tmp to ws_o
    GlobalTensor<float> wsO;
    wsO.SetGlobalBuffer(wsOBase_, coreIdx * t_.block_m * t_.dim);
    faL0cToGm(wsO, oL0C, t_.block_m, t_.dim);

    co1OQ_.FreeTensor(oL0C);
    pL1Q_.FreeTensor(pL1);
    vL1Q_.FreeTensor(vL1);

    // Signal AIV: O_tmp is ready
    CrossCoreSetFlag<0x2, PIPE_FIX>(FA_FLAG_O_READY);
}

// ================================================================
// AIV_ConsStep: Read O_tmp, merge into accumulator
// ================================================================
__aicore__ inline void FlashAttentionScoreKernel::AIV_ConsStep(int32_t t)
{
    int32_t vid = GetSubBlockIdx();
    int32_t coreIdx = GetBlockIdx() / GetSubBlockNum();

    // Read O_tmp for my half from ws_o
    int32_t oOffset = vid * halfM_ * t_.dim;
    int32_t oElems = halfM_ * t_.dim;

    LocalTensor<float> oTmpLocal;
    viQ_.AllocTensor<float>(oTmpLocal);
    GlobalTensor<float> wsO;
    wsO.SetGlobalBuffer(wsOBase_, coreIdx * t_.block_m * t_.dim);
    faGmToUbPad(oTmpLocal, wsO[oOffset], oElems);
    viQ_.EnQue(oTmpLocal);

    LocalTensor<float> oTmp = oTmpBuf_.Get<float>();
    viQ_.DeQue<float>(oTmpLocal);
    DataCopy(oTmp, oTmpLocal, oElems);
    viQ_.FreeTensor(oTmpLocal);

    // Merge: acc_o += O_tmp
    LocalTensor<float> o = accOBuf_.Get<float>();
    Add(o, o, oTmp, oElems);
}

// ================================================================
// AIV_Epilogue: Normalize and write output
// ================================================================
__aicore__ inline void FlashAttentionScoreKernel::AIV_Epilogue()
{
    int32_t vid = GetSubBlockIdx();
    LocalTensor<float> o  = accOBuf_.Get<float>();
    LocalTensor<float> se = sumexpBuf_.Get<float>();

    // acc_o /= sumexp (per row)
    for (int32_t h = 0; h < halfM_; ++h) {
        float invSe = 1.0f / se.GetValue(h);
        Muls(o[h * t_.dim], o[h * t_.dim], invSe, t_.dim);
    }

    // Cast to fp16 and write to output
    int32_t oOff = bz_ * t_.seq_len * t_.dim + (bx_ * t_.block_m + vid * halfM_) * t_.dim;
    int32_t oElems = halfM_ * t_.dim;

    LocalTensor<half> oHalf;
    voQ_.AllocTensor<half>(oHalf);
    Cast(oHalf, o, RoundMode::CAST_ROUND, oElems);

    GlobalTensor<half> oGm;
    oGm.SetGlobalBuffer(oBase_, t_.batch * t_.seq_len * t_.dim);
    faUbToGmPad(oGm[oOff], oHalf, oElems);
    voQ_.FreeTensor(oHalf);
}

