#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "flash_attention_score_kernel.h"
#include "aclrtlaunch_flash_attention_score_with_large_head_dim.h"

namespace ascend_kernel {

at::Tensor flash_attention_score_with_large_head_dim(
    const at::Tensor &query,
    const at::Tensor &key,
    const at::Tensor &value,
    double scale_value,
    int64_t head_num)
{
    // Input validation
    TORCH_CHECK(query.dim() == 3, "query must be 3D [batch, seq_len, dim]");
    TORCH_CHECK(query.sizes() == key.sizes(), "query and key shape mismatch");
    TORCH_CHECK(query.sizes() == value.sizes(), "query and value shape mismatch");
    TORCH_CHECK(query.scalar_type() == at::kHalf, "Only float16 supported");
    TORCH_CHECK(query.is_contiguous() && key.is_contiguous() && value.is_contiguous(),
                "Contiguous inputs required");

    int32_t batch   = static_cast<int32_t>(query.size(0));
    int32_t seq_len = static_cast<int32_t>(query.size(1));
    int32_t dim     = static_cast<int32_t>(query.size(2));

    // Adaptive tiling: block_m/n based on dim
    // L1 budget ~192KB: Q[block_m, dim] + K[block_n, dim] ≤ 130KB (2 * fp16 bytes)
    // block_m * dim * 2 ≤ 130000 → block_m ≤ 65000 / dim
    int32_t block_m, block_n;
    if (dim <= 512) {
        block_m = 64; block_n = 64;
    } else {
        block_m = 32; block_n = 32;
    }

    int32_t m_blocks    = (seq_len + block_m - 1) / block_m;
    int32_t kv_loops    = (seq_len + block_n - 1) / block_n;
    int32_t total_cores = m_blocks * batch;

    // Get hardware info
    auto platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(platform->GetCoreNumAiv());
    uint64_t ubSize;
    platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Tiling data
    FlashAttentionTiling tiling;
    tiling.batch       = batch;
    tiling.seq_len     = seq_len;
    tiling.dim         = dim;
    tiling.block_m     = block_m;
    tiling.block_n     = block_n;
    tiling.kv_loops    = kv_loops;
    tiling.m_blocks    = m_blocks;
    tiling.total_cores = total_cores;
    tiling.scale_value = static_cast<float>(scale_value);

    // Allocate tiling on CPU then copy to NPU
    auto tilingCpu = at::empty({static_cast<int64_t>(sizeof(FlashAttentionTiling))},
                                at::device(at::kCPU).dtype(at::kByte));
    auto *tilingPtr = reinterpret_cast<FlashAttentionTiling *>(tilingCpu.data_ptr());
    *tilingPtr = tiling;
    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);

    // Allocate output tensor (float16, same shape as input)
    auto output = at::empty({static_cast<int64_t>(batch), static_cast<int64_t>(seq_len), static_cast<int64_t>(dim)},
                             at::device(at::kPrivateUse1).dtype(at::kHalf));

    // Workspace sizes
    int64_t wsSSize  = static_cast<int64_t>(total_cores) * block_m * block_n * sizeof(float);
    int64_t wsPSize  = static_cast<int64_t>(total_cores) * block_m * block_n * sizeof(int16_t); // half
    int64_t wsOSize  = static_cast<int64_t>(total_cores) * block_m * dim * sizeof(float);

    auto wsS = at::empty({wsSSize}, at::device(at::kPrivateUse1).dtype(at::kByte));
    auto wsP = at::empty({wsPSize}, at::device(at::kPrivateUse1).dtype(at::kByte));
    auto wsO = at::empty({wsOSize}, at::device(at::kPrivateUse1).dtype(at::kByte));

    // EXEC_KERNEL_CMD requires all params as lvalues
    int64_t blockDim = total_cores;
    EXEC_KERNEL_CMD(flash_attention_score_with_large_head_dim, blockDim,
                    query, key, value, output, wsS, wsP, wsO, tilingNpu);

    return output;
}

} // namespace ascend_kernel
