{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * Licensed under CANN Open Software License Agreement Version 2.0.
 *
 * FlashAttentionScoreWithLargeHeadDim AscendC kernel.
 *
 * Design: Pure-Vector kernel (KERNEL_TYPE_VECTOR) using GM workspace for
 * intermediate S and O_tmp matrices.  This avoids the CO1→GM Fixpipe path
 * which is unsupported on dav_m200.
 *
 * Per-core computation:
 *  1. Load Q[block_m, dim] to UB (tiled along dim if needed)
 *  2. For each KV block t:
 *    a. Load K[t], compute S[block_m, block_n] = Q @ K[t]^T via tiled matmul (UB)
 *    b. Apply scale, online softmax, store P to ws_p
 *    c. Load V[t], compute O_tmp[block_m, dim] = P @ V[t] via tiled matmul (UB)
 *    d. Merge O_tmp into running O accumulator
 *  3. Normalize O = O / sumexp, cast to fp16, write to output
 */

#ifndef FLASH_ATTENTION_SCORE_KERNEL_H
#define FLASH_ATTENTION_SCORE_KERNEL_H

#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t C0 = DEFAULT_C0_SIZE;  // 16 for fp16

// Tiling data from host
#pragma pack(push, 8)
struct FlashAttentionTiling {
    int32_t batch;
    int32_t seq_len;
    int32_t dim;
    int32_t block_m;
    int32_t block_n;
    int32_t tile_dim;       // dim tiling size for UB-fit
    int32_t kv_loops;
    int32_t m_blocks;
    int32_t total_cores;
    int32_t dim_tiles;      // number of tiles along dim
    float   scale_value;
    int32_t row_per_core;   // rows per core (same as block_m for full blocks)
    int32_t block_n_tail;   // tail block_n for last KV step
};
#pragma pack(pop)

__aicore__ inline void faCopyTiling(FlashAttentionTiling *t, GM_ADDR gm)
{
    auto src = reinterpret_cast<__gm__ int32_t *>(gm);
    auto dst = reinterpret_cast<int32_t *>(t);
    for (uint32_t i = 0; i < sizeof(FlashAttentionTiling) / sizeof(int32_t); ++i)
        dst[i] = src[i];
}

// ============ UB Matmul tile helper ============
// Compute C[M, N] = A[M, K] @ B[K, N] in UB using Mul+ReduceSum
// A, B, C are all on UB, in fp32 for accumulation
template<typename AccT>
__aicore__ inline void UbMatmul(LocalTensor<AccT> &C, const LocalTensor<AccT> &A,
                                 const LocalTensor<AccT> &B,
                                 int32_t M, int32_t K, int32_t N,
                                 LocalTensor<uint8_t> &rwBuf,
                                 bool init)
{
    // For each m in [0, M):
    //   For each n in [0, N):
    //     C[m*N + n] += sum_k(A[m*K + k] * B[k*N + n])
    // Use chunked approach: tile K in chunks of chunkK
    int32_t chunkK = 64;  // How many K elements to process at once
    for (int32_t kc = 0; kc < K; kc += chunkK) {
        int32_t kSz = (kc + chunkK > K) ? (K - kc) : chunkK;
        int32_t elems = M * kSz * N;
        if (elems <= 0) continue;

        // Temporary product buffer: tileBuf[M, kSz, N] — actually tileBuf[M*kSz*N]
        // For each m, do outer product-like accumulation
        for (int32_t m = 0; m < M; ++m) {
            for (int32_t k = 0; k < kSz; ++k) {
                AccT aVal = A[m * K + kc + k];
                // Scale entire row of B by aVal and add to C[m, :]
                Muls(C[m * N], C[m * N], aVal, N);  // scale current row — NO, this is wrong
            }
        }
    }
}
// NOTE: The above UB matmul approach is too complex/slow.
// We use a simpler approach: decompose into per-output-element computation.

// ============ Correct UB Matmul ============
// C[m, n] = sum_k A[m, k] * B[k, n]
// For each (m, n), we compute dot product along K.
// With vector ops: compute per-element dot product using Mul+ReduceSum.

template<typename AccT>
__aicore__ inline void UbDotProduct(LocalTensor<AccT> &C, const LocalTensor<AccT> &A,
                                     const LocalTensor<AccT> &B,
                                     int32_t M, int32_t K, int32_t N,
                                     LocalTensor<uint8_t> &rwBuf,
                                     bool init)
{
    // For each m, compute C[m, :] = sum_k A[m, k] * B[k, :]
    // This is done using Mul + ReduceSum row-by-row
    // For large K, we tile in chunks of size that fits rwBuf
    int32_t rwElems = rwBuf.GetSize() / sizeof(AccT);
    int32_t maxKchunk = rwElems / N;  // each chunk must fit: chunkK * N

    for (int32_t m = 0; m < M; ++m) {
        int32_t cOff = m * N;
        if (init) {
            Duplicate<AccT>(C[cOff], (AccT)0.0f, N);
        }
        // Process K in chunks
        for (int32_t kc = 0; kc < K; kc += maxKchunk) {
            int32_t kSz = (kc + maxKchunk > K) ? (K - kc) : maxKchunk;
            if (kSz <= 0) break;

            // Allocate temp for products: [kSz, N]
            int32_t tmpElems = kSz * N;
            int32_t tmpBytes = tmpElems * sizeof(AccT);
            LocalTensor<AccT> prod = rwBuf.Get<AccT>().ReinterpretCast<AccT>();

            // prod[k, n] = A[m, kc+k] * B[kc+k, n]  — broadcast A[m,kc+k] across N elements
            // Do Mul element by element since A is only a single value per K element
            for (int32_t k = 0; k < kSz; ++k) {
                AccT aVal = A[m * K + kc + k].GetValue(0);
                // Handle scalar case: prod = aVal * B[kc+k, :]
                // Use Muls for scalar-tensor multiplication
                if constexpr (sizeof(AccT) == sizeof(float)) {
                    // For fp32, broadcast via Duplicate then Mul
                    LocalTensor<AccT> aVec = rwBuf.Get<AccT>().ReinterpretCast<AccT>();
                    Duplicate<AccT>(aVec, aVal, N);
                    Mul(prod[k * N], aVec, B[(kc + k) * N], N);
                } else {
                    Muls(prod[k * N], B[(kc + k) * N], aVal, N);
                }
            }

            // Reduce along k dimension: C[m, :] += reduce_sum(prod, dim=0)
            // Use ReduceSum over kSz rows of N columns
            PendInfo pInfo;
            ReduceSum<AccT>(C[cOff], prod, rwBuf.Get<AccT>(), kSz, N, N, N, 1);
        }
    }
}

// ============ Main Kernel Class ============
class FlashAttentionScoreKernel {
public:
    __aicore__ inline void Init(GM_ADDR q, GM_ADDR k, GM_ADDR v, GM_ADDR output,
                                GM_ADDR ws_s, GM_ADDR ws_o,
                                GM_ADDR tilingGM, AscendC::TPipe *pipe);
    __aicore__ inline void Process();

private:
    FlashAttentionTiling t_;
    int32_t bx_, bz_;   // seq-block, batch index
    int32_t block_m_;   // rows for this core

    __gm__ half *qBase_, *kBase_, *vBase_, *oBase_;
    __gm__ float *wsSBase_, *wsOBase_;

    // UB buffers
    TQue<TPosition::VECIN, 1>  viQ_;
    TQue<TPosition::VECOUT, 1> voQ_;

    TBuf<TPosition::VECCALC> qBuf_;      // [block_m, tile_dim] fp16
    TBuf<TPosition::VECCALC> kBuf_;      // [block_n, tile_dim] fp16
    TBuf<TPosition::VECCALC> vBuf_;      // [block_n, tile_dim] fp16
    TBuf<TPosition::VECCALC> sBuf_;      // [block_m, block_n] fp32 — S matrix (per KV step)
    TBuf<TPosition::VECCALC> pBuf_;      // [block_m, block_n] fp16 — P matrix (softmax output)
    TBuf<TPosition::VECCALC> oTmpBuf_;   // [block_m, tile_dim] fp32 — O_tmp per KV step
    TBuf<TPosition::VECCALC> accOBuf_;   // [block_m, dim] fp32 — running O accumulator
    TBuf<TPosition::VECCALC> sumexpBuf_; // [block_m] fp32 — running sumexp
    TBuf<TPosition::VECCALC> miBuf_;     // [block_m] fp32 — running max
    TBuf<TPosition::VECCALC> rwBuf_;     // reduce workspace
    TPipe *pipe_;
};

// ======== Init ========
__aicore__ inline void FlashAttentionScoreKernel::Init(
    GM_ADDR q, GM_ADDR k, GM_ADDR v, GM_ADDR output,
    GM_ADDR ws_s, GM_ADDR ws_o,
    GM_ADDR tilingGM, AscendC::TPipe *pipe)
{
    pipe_ = pipe;
    faCopyTiling(&t_, tilingGM);

    int32_t coreIdx = GetBlockIdx();
    bz_ = coreIdx / t_.m_blocks;
    bx_ = coreIdx % t_.m_blocks;
    block_m_ = t_.block_m;

    qBase_ = reinterpret_cast<__gm__ half *>(q);
    kBase_ = reinterpret_cast<__gm__ half *>(k);
    vBase_ = reinterpret_cast<__gm__ half *>(v);
    oBase_ = reinterpret_cast<__gm__ half *>(output);
    wsSBase_ = reinterpret_cast<__gm__ float *>(ws_s);
    wsOBase_ = reinterpret_cast<__gm__ float *>(ws_o);

    int32_t szQBuf  = block_m_ * t_.tile_dim;
