#ifndef FLASH_ATTENTION_SCORE_KERNEL_H
#define FLASH_ATTENTION_SCORE_KERNEL_H

#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t CUBE_BASE_K = 128;
constexpr int32_t CUBE_BASE_N = 128;

// Sync flags (mode 0x2 for AIC<->AIV)
#define FA_FLAG_S   0x08   // S ready (AIC→AIV)
#define FA_FLAG_P   0x09   // P ready (AIV→AIC)
#define FA_FLAG_O   0x0A   // O_tmp ready (AIC→AIV)

#pragma pack(push, 8)
struct FlashAttentionTiling {
    int32_t batch;
    int32_t seq_len;
    int32_t dim;
    int32_t block_m;
    int32_t block_n;
    int32_t kv_loops;
    int32_t block_n_tail;
    int32_t m_blocks;
    int32_t total_cores;
    float   scale_value;
};
#pragma pack(pop)

__aicore__ inline void faCopyTiling(FlashAttentionTiling *t, GM_ADDR gm)
{
    auto src = reinterpret_cast<__gm__ int32_t *>(gm);
    auto dst = reinterpret_cast<int32_t *>(t);
    uint32_t n = sizeof(FlashAttentionTiling) / sizeof(int32_t);
    for (uint32_t i = 0; i < n; ++i) dst[i] = src[i];
}

// L1 helpers
template<typename T>
__aicore__ inline void faNd2Nz(const LocalTensor<T> &dst, const GlobalTensor<T> &src,
                               uint32_t m, uint32_t n, uint32_t ld)
{
    Nd2NzParams p; p.ndNum = 1; p.nValue = m; p.dValue = n;
    p.srcNdMatrixStride = 0; p.srcDValue = ld;
    p.dstNzC0Stride = m; p.dstNzNStride = 1; p.dstNzMatrixStride = 0;
    DataCopy(dst, src, p);
}

template<typename T>
__aicore__ inline void faL1ToL0A(const LocalTensor<T> &dst, const LocalTensor<T> &src,
                                  uint32_t m, uint32_t k, uint32_t cc)
{
    LoadData3DParamsV2<T> p;
    p.l1H = 1; p.l1W = cc; p.channelSize = k; p.kExtension = k; p.mExtension = m;
    p.strideH = 1; p.strideW = 1; p.filterH = 1; p.filterW = 1;
    p.dilationFilterH = 1; p.dilationFilterW = 1;
    LoadData(dst, src, p);
}

template<typename T>
__aicore__ inline void faL1ToL0B(const LocalTensor<T> &dst, const LocalTensor<T> &src,
                                  uint32_t n, uint32_t k, uint32_t cc)
{
    LoadData3DParamsV2<T> p;
    p.l1H = 1; p.l1W = cc; p.channelSize = n; p.kExtension = n; p.mExtension = k;
    p.strideH = 1; p.strideW = 1; p.filterH = 1; p.filterW = 1;
    p.dilationFilterH = 1; p.dilationFilterW = 1;
    LoadData(dst, src, p);
}

template<typename T>
__aicore__ inline void faFixpipeC1ToGm(const GlobalTensor<T> &dst, const LocalTensor<T> &src,
                                        uint32_t baseM, uint32_t curN)
{
    FixpipeParamsV220 p;
    p.nSize = curN; p.mSize = baseM;
    p.srcStride = baseM; p.dstStride = curN;
    p.ndNum = 1; p.srcNdStride = 0; p.dstNdStride = 0;
    Fixpipe(dst, src, p);
}

// UB helpers
template<typename T>
__aicore__ inline void faGmToUb(LocalTensor<T> &local, const GlobalTensor<T> &global,
                                 uint32_t bytes)
{
    DataCopyExtParams<T> ext = {1, static_cast<uint16_t>(bytes / DEFAULT_C0_SIZE), 0, 0};
    DataCopyPadExtParams<T> pad = {false, 0, 0, 0};
    DataCopyPad(local, global, ext, pad);
}

template<typename T>
__aicore__ inline void faUbToGm(const GlobalTensor<T> &global, const LocalTensor<T> &local,
                                 uint32_t bytes)
{
    DataCopyExtParams<T> ext = {1, static_cast<uint16_t>(bytes / DEFAULT_C0_SIZE), 0, 0};
    DataCopyPad(global, local, ext);
}


class FlashAttentionScoreKernel {
public:
    __aicore__ inline void Init(GM_ADDR q, GM_ADDR k, GM_ADDR v, GM_ADDR output,
                                GM_ADDR ws_s, GM_ADDR ws_p, GM_ADDR ws_o,
                                GM_ADDR tilingGM, TPipe *pipe);
    __aicore__ inline void Process();

private:
    FlashAttentionTiling t_;
    int32_t bx_, bz_, coreIdx_;

    __gm__ half  *qBase_, *kBase_, *vBase_, *oBase_;
    __gm__ float *wsSBase_, *wsOBase_;
    __gm__ half  *wsPBase_;

    // AIC buffers
    TQue<TPosition::A1, 1>  qL1Q_, pL1Q_;  // persistent read
    TQue<TPosition::B1, 1>  kL1Q_, vL1Q_;  // per-step read
    TQue<TPosition::A2, 1>  a2Q_;
    TQue<TPosition::B2, 1>  b2Q_;
    TQue<TPosition::CO1, 1> co1Q_;

    // AIV buffers
    TQue<TPosition::VECIN, 1>  viQ_;
    TQue<TPosition::VECOUT, 1> voQ_;
    TBuf<TPosition::VECCALC> accOBuf_;     // [block_m, dim] float
    TBuf<TPosition::VECCALC> sumexpBuf_;   // [block_m] float
    TBuf<TPosition::VECCALC> miBuf_;       // [block_m] float
    TBuf<TPosition::VECCALC> scoreBuf_;    // [block_m // 2, block_n] float
    TBuf<TPosition::VECCALC> miOldBuf_;    // [block_m // 2] float
    TBuf<TPosition::VECCALC> rwBuf_;       // reduce workspace
    TBuf<TPosition::VECCALC> seIBuf_;      // [block_m // 2] float
    TBuf<TPosition::VECCALC> oTmpBuf_;     // [block_m // 2, dim] float

    int32_t halfM_;  // block_m / 2 for sub-block processing

    // Pipeline steps
    __aicore__ inline void AIC_Prod(int32_t t);
    __aicore__ inline void AIC_Cons(int32_t t);
    __aicore__ inline void AIV_Prod(int32_t t);
    __aicore__ inline void AIV_Cons(int32_t t);
    __aicore__ inline void AIV_Epi();
};

// ======== Init ========
__aicore__ inline void FlashAttentionScoreKernel::Init(
    GM_ADDR q, GM_ADDR k, GM_ADDR v, GM_ADDR output,
    GM_ADDR ws_s, GM_ADDR ws_p, GM_ADDR ws_o,
    GM_ADDR tilingGM, TPipe *pipe)
{
    faCopyTiling(&t_, tilingGM);
    coreIdx_ = GetBlockIdx() / GetSubBlockNum();
    bz_ = coreIdx_ / t_.m_blocks;
    bx_ = coreIdx_ % t_.m_blocks;
    halfM_ = t_.block_m / 2;

    qBase_  = reinterpret_cast<__gm__ half *>(q);
    kBase_  = reinterpret_cast<__gm__ half *>(k);
    vBase_  = reinterpret_cast<__gm__ half *>(v);
    oBase_  = reinterpret_cast<__gm__ half *>(output);
    wsSBase_ = reinterpret_cast<__gm__ float *>(ws_s);
    wsPBase_ = reinterpret_cast<__gm__ half *>(ws_p);
    wsOBase_ = reinterpret_cast<__gm__ float *>(ws_o);

    int32_t szQ   = t_.block_m * t_.dim;
    int32_t szKN  = t_.block_n * t_.dim;
    int32_t szS   = t_.block_m * t_.block_n;
    int32_t szO   = t_.block_m * t_.dim;
    int32_t szHalfS = halfM_ * t_.block_n;
    int32_t szHalfO = halfM_ * t_.dim;
    int32_t szRow   = halfM_;

    if ASCEND_IS_AIC {
        pipe->InitBuffer(qL1Q_, 1, szQ * sizeof(half));
        pipe->InitBuffer(kL1Q_, 1, szKN * sizeof(half));
        pipe->InitBuffer(pL1Q_, 1, szS * sizeof(half));
        pipe->InitBuffer(vL1Q_, 1, szKN * sizeof(half));
        pipe->InitBuffer(a2Q_, 1, t_.block_m * CUBE_BASE_K * sizeof(half));
        pipe->InitBuffer(b2Q_, 1, t_.block_n * CUBE_BASE_K * sizeof(half));
        pipe->InitBuffer(co1Q_, 1, szS * sizeof(float));
    }

    if ASCEND_IS_AIV {
        pipe->InitBuffer(viQ_, 1, szHalfO * sizeof(float));
        pipe->InitBuffer(voQ_, 1, szHalfO * sizeof(half));
        pipe->InitBuffer(accOBuf_, szO * sizeof(float));
        pipe->InitBuffer(sumexpBuf_, t_.block_m * sizeof(float));
        pipe->InitBuffer(miBuf_, t_.block_m * sizeof(float));
        pipe->InitBuffer(scoreBuf_, szHalfS * sizeof(float));
        pipe->InitBuffer(miOldBuf_, szRow * sizeof(float));
        pipe->InitBuffer(rwBuf_, szHalfS * sizeof(float) * 3 / 4);
        pipe->InitBuffer(seIBuf_, szRow * sizeof(float));
        pipe->InitBuffer(oTmpBuf_, szHalfO * sizeof(float));
    }
}

// ======== Process ========
__aicore__ inline void FlashAttentionScoreKernel::Process()
{
    // --- AIC: preload Q ---
    if ASCEND_IS_AIC {
        LocalTensor<half> qL1;
        qL1Q_.AllocTensor<half>(qL1);
        GlobalTensor<half> qGm;
        qGm.SetGlobalBuffer(qBase_, t_.batch * t_.seq_len * t_.dim);
        int32_t qOff = bz_ * t_.seq_len * t_.dim + bx_ * t_.block_m * t_.dim;
        faNd2Nz(qL1, qGm[qOff], t_.block_m, t_.dim, t_.dim);
    }

    // --- AIV: init accumulators ---
    if ASCEND_IS_AIV {
        LocalTensor<float> o  = accOBuf_.Get<float>();
        LocalTensor<float> se = sumexpBuf_.Get<float>();
        LocalTensor<float> mi = miBuf_.Get<float>();
        Duplicate<float>(o, 0.0f, t_.block_m * t_.dim);
        Duplicate<float>(se, 0.0f, t_.block_m);
        Duplicate<float>(mi, -1.0e30f, t_.block_m);
    }

    // --- Main loop ---
    for (int32_t t = 0; t < t_.kv_loops; ++t) {
        if ASCEND_IS_AIC { AIC_Prod(t); }
        if ASCEND_IS_AIV { AIV_Prod(t); }

        if ASCEND_IS_AIC { AIC_Cons(t); }
        if ASCEND_IS_AIV { AIV_Cons(t); }
    }

    if ASCEND_IS_AIV { AIV_Epi(); }
}

// ======== AIC: Q @ K^T → S ========
__aicore__ inline void FlashAttentionScoreKernel::AIC_Prod(int32_t t)
{
    int32_t bn = (t == t_.kv_loops - 1 && t_.block_n_tail > 0) ? t_.block_n_tail : t_.block_n;

    // Q already preloaded in qL1Q_

    // Load K[t]
    LocalTensor<half> kL1;
    kL1Q_.AllocTensor<half>(kL1);
    {
        GlobalTensor<half> kGm;
        kGm.SetGlobalBuffer(kBase_, t_.batch * t_.seq_len * t_.dim);
        int32_t kOff = bz_ * t_.seq_len * t_.dim + t * t_.block_n * t_.dim;
        faNd2Nz(kL1, kGm[kOff], bn, t_.dim, t_.dim);
        PipeBarrier<PIPE_MTE2>();
    }

    LocalTensor<half> qL1;
    qL1Q_.AllocTensor<half>(qL1);

    // MMA: S = Q[block_m, dim] @ K^T[dim, bn]
    int32_t kChunks = (t_.dim + CUBE_BASE_K - 1) / CUBE_BASE_K;
    int32_t ccQ = t_.dim / DEFAULT_C0_SIZE;
    int32_t ccK = t_.dim / DEFAULT_C0_SIZE;

    LocalTensor<float> c1;
    co1Q_.AllocTensor<float>(c1);

    for (int32_t kc = 0; kc < kChunks; ++kc) {
        int32_t kOff = kc * CUBE_BASE_K;
        int32_t kSz  = (kOff + CUBE_BASE_K > t_.dim) ? (t_.dim - kOff) : CUBE_BASE_K;
        if (kSz <= 0) break;

        LocalTensor<half> a2;
        a2Q_.AllocTensor<half>(a2);
        faL1ToL0A(a2, qL1[kOff / DEFAULT_C0_SIZE * ccQ], t_.block_m, kSz, ccQ);

        LocalTensor<half> b2;
        b2Q_.AllocTensor<half>(b2);
        faL1ToL0B(b2, kL1[kOff / DEFAULT_C0_SIZE * ccK], bn, kSz, ccK);

        PipeBarrier<PIPE_MTE3>();
        Mmad(c1, a2, b2, t_.block_m, kSz, bn, (kc == 0) ? 1 : 0);

        a2Q_.FreeTensor(a2);
        b2Q_.FreeTensor(b2);
    }

    // Enque CO1 result
    co1Q_.EnQue(c1);
    // DeQue to get fixpipe-able tensor
    LocalTensor<float> c1Out = co1Q_.DeQue<float>();

    // Fixpipe S to ws_s
    int32_t sOff = coreIdx_ * t_.block_m * t_.block_n;
    GlobalTensor<float> wsS;
    wsS.SetGlobalBuffer(wsSBase_, t_.total_cores * t_.block_m * t_.block_n);
    faFixpipeC1ToGm(wsS[sOff], c1Out, t_.block_m, bn);

    co1Q_.FreeTensor(c1Out);
    qL1Q_.FreeTensor(qL1);
    kL1Q_.FreeTensor(kL1);

    // Signal AIV: S ready
    CrossCoreSetFlag<0x2, PIPE_FIX>(FA_FLAG_S);
    // Wait for AIV: P ready
    CrossCoreWaitFlag<0x2>(FA_FLAG_P);
}

// ======== AIV: Softmax(S) → P ========
__aicore__ inline void FlashAttentionScoreKernel::AIV_Prod(int32_t t)
{
    int32_t bn = (t == t_.kv_loops - 1 && t_.block_n_tail > 0) ? t_.block_n_tail : t_.block_n;
    int32_t vid = GetSubBlockIdx();

    // Wait for S
    CrossCoreWaitFlag<0x2>(FA_FLAG_S);

    // Read my half of S
    int32_t halfRowS = halfM_ * bn;
    int32_t sCoreOff = coreIdx_ * t_.block_m * t_.block_n;
    int32_t sOff = sCoreOff + vid * halfRowS;

    LocalTensor<float> sIn;
    viQ_.AllocTensor<float>(sIn);
    {
        GlobalTensor<float> wsS;
        wsS.SetGlobalBuffer(wsSBase_, t_.total_cores * t_.block_m * t_.block_n);
        faGmToUb(sIn, wsS[sOff], halfRowS * sizeof(float));
        viQ_.EnQue(sIn);
    }

    LocalTensor<float> score = scoreBuf_.Get<float>();
    viQ_.DeQue<float>(sIn);

    // S *= scale
    Muls(score, sIn, t_.scale_value, halfRowS);
    viQ_.FreeTensor(sIn);

    // Online softmax
    LocalTensor<float> mi    = miBuf_.Get<float>();
    LocalTensor<float> miOld = miOldBuf_.Get<float>();
    LocalTensor<float> rw    = rwBuf_.Get<float>();
    LocalTensor<float> seI   = seIBuf_.Get<float>();

    // miOld = old_max (per-row of current block)
    DataCopyParams rowView = {1, static_cast<uint16_t>(halfM_ * sizeof(float) / DEFAULT_C0_SIZE), 0, 0};
    DataCopy(miOld, mi[vid * halfM_], halfM_);

    // new_max = row_max(S)
    // For simplicity: ReduceMax on [halfM_, bn] along axis=1
    ReduceMax<float, false>(mi[vid * halfM_], score, rw, halfM_, bn, bn, 1);

    // mi_new = max(old_max, new_max) — mi already has new_max from ReduceMax
    Max(mi[vid * halfM_], mi[vid * halfM_], miOld, halfM_);

    // alpha = exp(old_max - mi_new)
    Sub(miOld, miOld, mi[vid * halfM_], halfM_);
    Exp(miOld, miOld, halfM_);

    // S = exp(S - mi_new)
    for (int32_t h = 0; h < halfM_; ++h) {
        float negM = -mi[vid * halfM_ + h].GetValue(0);
        Adds(score[h * bn], score[h * bn], negM, bn);
    }
    Exp(score, score, halfRowS);

    // sumexp_i = row_sum(exp(S - mi_new))
    ReduceSum<float>(seI, score, rw, halfM_, bn, bn, 1);

    // Rescale acc_o: acc_o[h, :] *= alpha[h]
    LocalTensor<float> o = accOBuf_.Get<float>();
    int32_t oOff = vid * halfM_ * t_.dim;
    for (int32_t h = 0; h < halfM_; ++h) {
        Muls(o[oOff + h * t_.dim], o[oOff + h * t_.dim], miOld[h], t_.dim);
    }

    // sumexp = alpha * sumexp + sumexp_i
    LocalTensor<float> se = sumexpBuf_.Get<float>();
    Mul(se[vid * halfM_], se[vid * halfM_], miOld, halfM_);
    Add(se[vid * halfM_], se[vid * halfM_], seI, halfM_);

    // Write P = softmax(S) to ws_p (cast to fp16)
    int32_t pCoreOff = coreIdx_ * t_.block_m * t_.block_n;
    int32_t pOff = pCoreOff + vid * halfRowS;

    LocalTensor<half> pHalf;
    voQ_.AllocTensor<half>(pHalf);
    Cast(pHalf, score, RoundMode::CAST_ROUND, halfRowS);

    {
        GlobalTensor<half> wsP;
        wsP.SetGlobalBuffer(wsPBase_, t_.total_cores * t_.block_m * t_.block_n);
        faUbToGm(wsP[pOff], pHalf, halfRowS * sizeof(half));
    }
    voQ_.FreeTensor(pHalf);

    // Signal AIC: P ready
    CrossCoreSetFlag<0x2, PIPE_MTE2>(FA_FLAG_P);
    // Wait for O_tmp
    CrossCoreWaitFlag<0x2>(FA_FLAG_O);
}

// ======== AIC: P @ V → O_tmp ========
__aicore__ inline void FlashAttentionScoreKernel::AIC_Cons(int32_t t)
{
    // Load P from ws_p to L1
    LocalTensor<half> pL1;
    pL1Q_.AllocTensor<half>(pL1);
    {
        GlobalTensor<half> wsP;
        wsP.SetGlobalBuffer(wsPBase_, t_.total_cores * t_.block_m * t_.block_n);
        int32_t pOff = coreIdx_ * t_.block_m * t_.block_n;
        faNd2Nz(pL1, wsP[pOff], t_.block_m, t_.block_n, t_.block_n);
        PipeBarrier<PIPE_MTE2>();
    }

    // Load V[t]
    LocalTensor<half> vL1;
    vL1Q_.AllocTensor<half>(vL1);
    {
        GlobalTensor<half> vGm;
        vGm.SetGlobalBuffer(vBase_, t_.batch * t_.seq_len * t_.dim);
        int32_t vOff = bz_ * t_.seq_len * t_.dim + t * t_.block_n * t_.dim;
        faNd2Nz(vL1, vGm[vOff], t_.block_n, t_.dim, t_.dim);
        PipeBarrier<PIPE_MTE2>();
    }

    // O_tmp = P[block_m, block_n] @ V[block_n, dim]
    int32_t ccP = t_.block_n / DEFAULT_C0_SIZE;
    int32_t ccV = t_.dim / DEFAULT_C0_SIZE;

    LocalTensor<float> c1;
    co1Q_.AllocTensor<float>(c1);

    // Tile along dim (N axis) in CUBE_BASE_N chunks
    int32_t nChunks = (t_.dim + CUBE_BASE_N - 1) / CUBE_BASE_N;
    for (int32_t nc = 0; nc < nChunks; ++nc) {
        int32_t nOff = nc * CUBE_BASE_N;
        int32_t nSz  = (nOff + CUBE_BASE_N > t_.dim) ? (t_.dim - nOff) : CUBE_BASE_N;
        if (nSz <= 0) break;

        LocalTensor<half> a2;
        a2Q_.AllocTensor<half>(a2);
        faL1ToL0A(a2, pL1, t_.block_m, t_.block_n, ccP);

        LocalTensor<half> b2;
        b2Q_.AllocTensor<half>(b2);
        faL1ToL0B(b2, vL1[nOff / DEFAULT_C0_SIZE * ccV], nSz, t_.block_n, ccV);

        PipeBarrier<PIPE_MTE3>();
        int32_t c1Off = nOff / DEFAULT_C0_SIZE * t_.block_m;
        Mmad(c1[c1Off], a2, b2, t_.block_m, t_.block_n, nSz, (nc == 0) ? 1 : 0);

        a2Q_.FreeTensor(a2);
        b2Q_.FreeTensor(b2);
    }

    co1Q_.EnQue(c1);
    LocalTensor<float> c1Out = co1Q_.DeQue<float>();

    // Fixpipe O_tmp to ws_o
    int32_t oOff = coreIdx_ * t_.block_m * t_.dim;
    GlobalTensor<float> wsO;
    wsO.SetGlobalBuffer(wsOBase_, t_.total_cores * t_.block_m * t_.dim);
    faFixpipeC1ToGm(wsO[oOff], c1Out, t_.block_m, t_.dim);

    co1Q_.FreeTensor(c1Out);
    pL1Q_.FreeTensor(pL1);
    vL1Q_.FreeTensor(vL1);

    // Signal AIV: O_tmp ready
    CrossCoreSetFlag<0x2, PIPE_FIX>(FA_FLAG_O);
}

// ======== AIV: Merge O_tmp ========
__aicore__ inline void FlashAttentionScoreKernel::AIV_Cons(int32_t t)
{
    int32_t vid = GetSubBlockIdx();

    // Read O_tmp for my half
    int32_t oCoreOff = coreIdx_ * t_.block_m * t_.dim;
    int32_t oOff = oCoreOff + vid * halfM_ * t_.dim;
    int32_t oElems = halfM_ * t_.dim;

    LocalTensor<float> oIn;
    viQ_.AllocTensor<float>(oIn);
    {
        GlobalTensor<float> wsO;
        wsO.SetGlobalBuffer(wsOBase_, t_.total_cores * t_.block_m * t_.dim);
        faGmToUb(oIn, wsO[oOff], oElems * sizeof(float));
        viQ_.EnQue(oIn);
    }

    LocalTensor<float> oTmp = oTmpBuf_.Get<float>();
    viQ_.DeQue<float>(oIn);
    DataCopy(oTmp, oIn, oElems);
    viQ_.FreeTensor(oIn);

    // acc_o += O_tmp
    LocalTensor<float> o = accOBuf_.Get<float>();
    int32_t oBase = vid * halfM_ * t_.dim;
    Add(o[oBase], o[oBase], oTmp, oElems);
}

// ======== AIV: Epilogue ========
__aicore__ inline void FlashAttentionScoreKernel::AIV_Epi()
{
    int32_t vid = GetSubBlockIdx();
    LocalTensor<float> o  = accOBuf_.Get<float>();
    LocalTensor<float> se = sumexpBuf_.Get<float>();

    // acc_o /= sumexp per row
    int32_t oBase = vid * halfM_ * t_.dim;
    int32_t seOff = vid * halfM_;
    for (int32_t h = 0; h < halfM_; ++h) {
        float invSe = 1.0f / se[seOff + h].GetValue(0);
        Muls(o[oBase + h * t_.dim], o[oBase + h * t_.dim], invSe, t_.dim);
    }

    // Cast to fp16 and write to output
    LocalTensor<half> oHalf;
    voQ_.AllocTensor<half>(oHalf);
    Cast(oHalf, o[oBase], RoundMode::CAST_ROUND, halfM_ * t_.dim);

    int32_t outOff = bz_ * t_.seq_len * t_.dim + (bx_ * t_.block_m + vid * halfM_) * t_.dim;
    GlobalTensor<half> oGm;
    oGm.SetGlobalBuffer(oBase_, t_.batch * t_.seq_len * t_.dim);
    faUbToGm(oGm[outOff], oHalf, halfM_ * t_.dim * sizeof(half));
    voQ_.FreeTensor(oHalf);
}

