18	at::Tensor flash_attention_score_with_large_head_dim(
19	    const at::Tensor &query,
20	    const at::Tensor &key,
21	    const at::Tensor &value,
22	    double scale_value,
23	    int64_t head_num)
24	{
25	    // Input validation
26	    TORCH_CHECK(query.dim() == 3, "query must be 3D [batch, seq_len, dim]");
27	    TORCH_CHECK(query.sizes() == key.sizes(), "query and key shape mismatch");
28	    TORCH_CHECK(query.sizes() == value.sizes(), "query and value shape mismatch");
29	    TORCH_CHECK(query.scalar_type() == at::kHalf, "Only float16 supported");
30	    TORCH_CHECK(query.is_contiguous() && key.is_contiguous() && value.is_contiguous(),
31	                "Contiguous inputs required");
32	
33	    int32_t batch   = static_cast<int32_t>(query.size(0));
34	    int32_t seq_len = static_cast<int32_t>(query.size(1));
35	    int32_t dim     = static_cast<int32_t>(query.size(2));
36	
37	    // Adaptive tiling: block_m/n based on dim
38	    // L1 budget ~192KB: Q[block_m, dim] + K[block_n, dim] ≤ 130KB (2 * fp16 bytes)
39	    // block_m * dim * 2 ≤ 130000 → block_m ≤ 65000 / dim
40	    int32_t block_m, block_n;
41	    if (dim <= 512) {
42	        block_m = 64; block_n = 64;
43	    } else {
44	        block_m = 32; block_n = 32;
45	    }
46	
47	    int32_t m_blocks    = (seq_len + block_m - 1) / block_m;
48	    int32_t kv_loops    = (seq_len + block_n - 1) / block_n;
49	    int32_t total_cores = m_blocks * batch;
50	
51	    // Get hardware info
52	    auto platform = platform_ascendc::PlatformAscendCManager::GetInstance();
53	    int64_t coreNum = static_cast<int64_t>(platform->GetCoreNumAiv());
54	    uint64_t ubSize;
55	    platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
56	
57	    // Tiling data
58	    FlashAttentionTiling tiling;
59	    tiling.batch       = batch;
60	    tiling.seq_len     = seq_len;
61	    tiling.dim         = dim;
62	    tiling.block_m     = block_m;
63	    tiling.block_n     = block_n;
64	    tiling.kv_loops    = kv_loops;
65	    tiling.m_blocks    = m_blocks;
66	    tiling.total_cores = total_cores;
67	    tiling.scale_value = static_cast<float>(scale_value);
68	
69	    // Allocate tiling on CPU then copy to NPU
70	    auto tilingCpu = at::empty({static_cast<int64_t>(sizeof(FlashAttentionTiling))},
71	                                at::device(at::kCPU).dtype(at::kByte));
72	    auto *tilingPtr = reinterpret_cast<FlashAttentionTiling *>(tilingCpu.data_ptr());
73	    *tilingPtr = tiling;
74	    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);
75	
76	    // Allocate output tensor (float16, same shape as input)
77	    auto output = at::empty({static_cast<int64_t>(batch), static_cast<int64_t>(seq_len), static_cast<int64_t>(dim)},
78	                             at::device(at::kPrivateUse1).dtype(at::kHalf));
79	
80	    // Workspace sizes
81	    int64_t wsSSize  = static_cast<int64_t>(total_cores) * block_m * block_n * sizeof(float);
82	    int64_t wsPSize  = static_cast<int64_t>(total_cores) * block_m * block_n * sizeof(int16_t); // half
83	    int64_t wsOSize  = static_cast<int64_t>(total_cores) * block_m * dim * sizeof(float);
84	
85	    auto wsS = at::empty({wsSSize}, at::device(at::kPrivateUse1).dtype(at::kByte));
86	    auto wsP = at::empty({wsPSize}, at::device(at::kPrivateUse1).dtype(at::kByte));
87	    auto wsO = at::empty({wsOSize}, at::device(at::kPrivateUse1).dtype(at::kByte));
88	
89	    // EXEC_KERNEL_CMD requires all params as lvalues
90	    int64_t blockDim = total_cores;
91	    EXEC_KERNEL_CMD(flash_attention_score_with_large_head_dim, blockDim,
92	                    query, key, value, output, wsS, wsP, wsO, tilingNpu);
93	
94	    return output;
95	}
