 * FlashAttentionScoreWithLargeHeadDim AscendC kernel.
 * C/V fusion (KERNEL_TYPE_MIX_AIC_1_2) with per-step sequential sync.
 */

#ifndef FLASH_ATTENTION_SCORE_KERNEL_H
#define FLASH_ATTENTION_SCORE_KERNEL_H

#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t CBK = 128;
constexpr int32_t CBN = 128;

#define FA_FLAG_S 0x08
#define FA_FLAG_P 0x09
#define FA_FLAG_O 0x0A

#pragma pack(push, 8)
struct FlashAttentionTiling {
    int32_t batch; int32_t seq_len; int32_t dim;
    int32_t block_m; int32_t block_n;
    int32_t kv_loops; int32_t block_n_tail;
    int32_t m_blocks; int32_t total_cores;
    float   scale_value;
};
#pragma pack(pop)

__aicore__ inline void faTilingRead(FlashAttentionTiling *t, GM_ADDR gm) {
    auto s = reinterpret_cast<__gm__ int32_t*>(gm);
    auto d = reinterpret_cast<int32_t*>(t);
    for (uint32_t i=0; i<sizeof(FlashAttentionTiling)/sizeof(int32_t); ++i) d[i]=s[i];
}

// ===== L1 helpers =====
template<typename T>
__aicore__ inline void faNd2Nz(LocalTensor<T> &d, const GlobalTensor<T> &s, uint32_t m, uint32_t n, uint32_t ld) {
    Nd2NzParams p; p.ndNum=1; p.nValue=m; p.dValue=n;
    p.srcNdMatrixStride=0; p.srcDValue=ld;
    p.dstNzC0Stride=m; p.dstNzNStride=1; p.dstNzMatrixStride=0;
    DataCopy(d,s,p);
}

template<typename T>
__aicore__ inline void faL0A(LocalTensor<T> &d, const LocalTensor<T> &s, uint32_t m, uint32_t k, uint32_t cc) {
    LoadData3DParamsV2<T> p;
    p.l1H=1; p.l1W=cc; p.channelSize=k; p.kExtension=k; p.mExtension=m;
    p.strideH=1; p.strideW=1; p.filterH=1; p.filterW=1;
    p.dilationFilterH=1; p.dilationFilterW=1;
    LoadData(d,s,p);
}

template<typename T>
__aicore__ inline void faL0B(LocalTensor<T> &d, const LocalTensor<T> &s, uint32_t n, uint32_t k, uint32_t cc) {
    LoadData3DParamsV2<T> p;
    p.l1H=1; p.l1W=cc; p.channelSize=n; p.kExtension=n; p.mExtension=k;
    p.strideH=1; p.strideW=1; p.filterH=1; p.filterW=1;
    p.dilationFilterH=1; p.dilationFilterW=1;
    LoadData(d,s,p);
}

template<typename T>
__aicore__ inline void faFixpipe(GlobalTensor<T> &d, LocalTensor<T> &s, uint32_t baseM, uint32_t curN) {
    FixpipeParamsV220 p;
    p.nSize=curN; p.mSize=baseM; p.srcStride=baseM; p.dstStride=curN;
    p.ndNum=1; p.srcNdStride=0; p.dstNdStride=0;
    Fixpipe(d,s,p);
}

// ===== UB helpers =====
template<typename T>
__aicore__ inline void faUbIn(LocalTensor<T> &loc, const GlobalTensor<T> &gm, uint32_t bytes) {
    DataCopyExtParams<T> e={1, static_cast<uint16_t>(bytes/DEFAULT_C0_SIZE),0,0};
    DataCopyPadExtParams<T> p={false,0,0,0};
    DataCopyPad(loc,gm,e,p);
}

template<typename T>
__aicore__ inline void faUbOut(GlobalTensor<T> &gm, LocalTensor<T> &loc, uint32_t bytes) {
    DataCopyExtParams<T> e={1, static_cast<uint16_t>(bytes/DEFAULT_C0_SIZE),0,0};
    DataCopyPad(gm,loc,e);
}


class FlashAttentionScoreKernel {
public:
    __aicore__ inline void Init(GM_ADDR q,GM_ADDR k,GM_ADDR v,GM_ADDR o,
                                GM_ADDR wsS,GM_ADDR wsP,GM_ADDR wsO,
                                GM_ADDR tgm,TPipe *pipe);
    __aicore__ inline void Process();
private:
    FlashAttentionTiling t_;
    int32_t bx_,bz_,ci_;
    __gm__ half *qB_,*kB_,*vB_,*oB_;
    __gm__ float *wSB_,*wOB_;
    __gm__ half *wPB_;
    int32_t hM_;

    // AIC (depth>0 queues → return-value AllocTensor)
    TQue<TPosition::A1,1>  a1Q_; // Q persistent
    TQue<TPosition::B1,1>  b1Q_; // K/V per step
    TQue<TPosition::A2,1>  a2Q_;
    TQue<TPosition::B2,1>  b2Q_;
    TQue<TPosition::CO1,1> c1Q_;

    // AIV (depth=0 → ref-form AllocTensor)
    TQue<TPosition::VECIN,0>  viQ_;
    TQue<TPosition::VECOUT,0> voQ_;
    TBuf<TPosition::VECCALC> oBuf_,seBuf_,miBuf_;
    TBuf<TPosition::VECCALC> scBuf_,moBuf_,rwBuf_,siBuf_,otBuf_;
    TPipe *pipe_;

    __aicore__ inline void aicP(int32_t t);
    __aicore__ inline void aicC(int32_t t);
    __aicore__ inline void aivP(int32_t t);
    __aicore__ inline void aivC(int32_t t);
    __aicore__ inline void aivEpi();
};

// ===== Init =====
__aicore__ inline void FlashAttentionScoreKernel::Init(GM_ADDR q,GM_ADDR k,GM_ADDR v,GM_ADDR o,
    GM_ADDR wsS,GM_ADDR wsP,GM_ADDR wsO,GM_ADDR tgm,TPipe *pipe)
{
    pipe_=pipe; faTilingRead(&t_,tgm);
    ci_=GetBlockIdx()/GetSubBlockNum();
    bz_=ci_/t_.m_blocks; bx_=ci_%t_.m_blocks;
    hM_=t_.block_m/2;
    qB_=reinterpret_cast<__gm__ half*>(q); kB_=reinterpret_cast<__gm__ half*>(k);
    vB_=reinterpret_cast<__gm__ half*>(v); oB_=reinterpret_cast<__gm__ half*>(o);
    wSB_=reinterpret_cast<__gm__ float*>(wsS); wPB_=reinterpret_cast<__gm__ half*>(wsP);
    wOB_=reinterpret_cast<__gm__ float*>(wsO);

    int32_t szQ=t_.block_m*t_.dim, szKN=t_.block_n*t_.dim, szS=t_.block_m*t_.block_n;
    int32_t szO=t_.block_m*t_.dim, szHS=hM_*t_.block_n, szHO=hM_*t_.dim, szR=hM_;

    if ASCEND_IS_AIC {
        pipe->InitBuffer(a1Q_,1,szQ*sizeof(half));
        pipe->InitBuffer(b1Q_,1,szKN*sizeof(half));
        pipe->InitBuffer(a2Q_,1,t_.block_m*CBK*sizeof(half));
        pipe->InitBuffer(b2Q_,1,t_.block_n*CBK*sizeof(half));
        pipe->InitBuffer(c1Q_,1,szS*sizeof(float));
    }
    if ASCEND_IS_AIV {
        pipe->InitBuffer(viQ_,1,szHO*sizeof(float)*2);
        pipe->InitBuffer(voQ_,1,szHO*sizeof(half));
        pipe->InitBuffer(oBuf_,szO*sizeof(float));
        pipe->InitBuffer(seBuf_,t_.block_m*sizeof(float));
        pipe->InitBuffer(miBuf_,t_.block_m*sizeof(float));
        pipe->InitBuffer(scBuf_,szHS*sizeof(float));
        pipe->InitBuffer(moBuf_,szR*sizeof(float));
        pipe->InitBuffer(rwBuf_,szHS*sizeof(float)*3/4);
        pipe->InitBuffer(siBuf_,szR*sizeof(float));
        pipe->InitBuffer(otBuf_,szHO*sizeof(float));
    }
}

// ===== Process =====
__aicore__ inline void FlashAttentionScoreKernel::Process()
{
    if ASCEND_IS_AIC {
        // Preload Q to L1 (persistent)
        LocalTensor<half> qL1 = a1Q_.AllocTensor<half>();
        GlobalTensor<half> qGm; qGm.SetGlobalBuffer(qB_, t_.batch*t_.seq_len*t_.dim);
        int32_t qOff=bz_*t_.seq_len*t_.dim + bx_*t_.block_m*t_.dim;
        faNd2Nz(qL1,qGm[qOff],t_.block_m,t_.dim,t_.dim);
        a1Q_.EnQue(qL1);
    }

    if ASCEND_IS_AIV {
        LocalTensor<float> o=oBuf_.Get<float>(), se=seBuf_.Get<float>(), mi=miBuf_.Get<float>();
        Duplicate<float>(o,0.0f,t_.block_m*t_.dim);
        Duplicate<float>(se,0.0f,t_.block_m);
        Duplicate<float>(mi,-1.0e30f,t_.block_m);
    }

    for(int32_t t=0; t<t_.kv_loops; ++t){
        if ASCEND_IS_AIC { aicP(t); }
        if ASCEND_IS_AIV { aivP(t); }
        if ASCEND_IS_AIC { aicC(t); }
        if ASCEND_IS_AIV { aivC(t); }
    }
    if ASCEND_IS_AIV { aivEpi(); }
}

// ===== AIC Prod: Q@K^T → S =====
__aicore__ inline void FlashAttentionScoreKernel::aicP(int32_t t)
{
    int32_t bn=(t==t_.kv_loops-1&&t_.block_n_tail>0)?t_.block_n_tail:t_.block_n;

    // DeQue Q (persistent, re-DeQue each step)
    LocalTensor<half> qL1 = a1Q_.DeQue<half>();

    // Load K[t] to L1
    LocalTensor<half> kL1 = b1Q_.AllocTensor<half>();
    { GlobalTensor<half> kg; kg.SetGlobalBuffer(kB_,t_.batch*t_.seq_len*t_.dim);
      int32_t ko=bz_*t_.seq_len*t_.dim + t*t_.block_n*t_.dim;
      faNd2Nz(kL1,kg[ko],bn,t_.dim,t_.dim); }
    b1Q_.EnQue(kL1);
    LocalTensor<half> kL1r = b1Q_.DeQue<half>();

    // MMA Q[block_m,dim] @ K^T[dim,bn]
    int32_t kcC=(t_.dim+CBK-1)/CBK, ccQ=t_.dim/DEFAULT_C0_SIZE, ccK=t_.dim/DEFAULT_C0_SIZE;
    LocalTensor<float> c1 = c1Q_.AllocTensor<float>();
    for(int32_t kc=0; kc<kcC; ++kc){
        int32_t ko=kc*CBK, ks=(ko+CBK>t_.dim)?(t_.dim-ko):CBK; if(ks<=0)break;
        LocalTensor<half> a2=a2Q_.AllocTensor<half>();
        faL0A(a2,qL1[ko/DEFAULT_C0_SIZE*ccQ],t_.block_m,ks,ccQ);
        LocalTensor<half> b2=b2Q_.AllocTensor<half>();
        faL0B(b2,kL1r[ko/DEFAULT_C0_SIZE*ccK],bn,ks,ccK);
        PipeBarrier<PIPE_MTE3>();
        Mmad(c1,a2,b2,t_.block_m,ks,bn,(kc==0)?1:0);
        a2Q_.FreeTensor(a2); b2Q_.FreeTensor(b2);
    }

    c1Q_.EnQue(c1);
    LocalTensor<float> c1o=c1Q_.DeQue<float>();
    int32_t so=ci_*t_.block_m*t_.block_n;
    { GlobalTensor<float> w; w.SetGlobalBuffer(wSB_,t_.total_cores*t_.block_m*t_.block_n);
      faFixpipe(w[so],c1o,t_.block_m,bn); }
    c1Q_.FreeTensor(c1o);
    b1Q_.FreeTensor(kL1r);
    // Don't free qL1 — re-DeQue'd next step (or freed at Co1Q's next cycle)

    CrossCoreSetFlag<0x2,PIPE_FIX>(FA_FLAG_S);
    CrossCoreWaitFlag<0x2>(FA_FLAG_P);
}

// ===== AIV Prod: softmax(S) → P =====
__aicore__ inline void FlashAttentionScoreKernel::aivP(int32_t t)
{
    int32_t bn=(t==t_.kv_loops-1&&t_.block_n_tail>0)?t_.block_n_tail:t_.block_n;
    int32_t vid=GetSubBlockIdx();
    CrossCoreWaitFlag<0x2>(FA_FLAG_S);

    int32_t hRS=hM_*bn, scOff=ci_*t_.block_m*t_.block_n + vid*hRS;
    LocalTensor<float> sIn; viQ_.AllocTensor<float>(sIn);
    { GlobalTensor<float> w; w.SetGlobalBuffer(wSB_,t_.total_cores*t_.block_m*t_.block_n);
      faUbIn(sIn,w[scOff],hRS*sizeof(float)); }
    viQ_.EnQue(sIn);

    LocalTensor<float> sc=scBuf_.Get<float>();
    viQ_.DeQue<float>(sIn);
    Muls(sc,sIn,t_.scale_value,hRS);
    viQ_.FreeTensor(sIn);

    LocalTensor<float> mi=miBuf_.Get<float>(), mo=moBuf_.Get<float>();
    LocalTensor<float> rw=rwBuf_.Get<float>(), si=siBuf_.Get<float>();

    // Online softmax
    DataCopyParams rp={1,static_cast<uint16_t>(hM_*sizeof(float)/DEFAULT_C0_SIZE),0,0};
    DataCopy(mo,mi[vid*hM_],hM_); // mo=m_old

    ReduceMax<float,false>(mi[vid*hM_],sc,rw,hM_,bn,bn,1); // mi_new=row_max(S)
    Max(mi[vid*hM_],mi[vid*hM_],mo,hM_); // mi_new=max(old,row_max)
    Sub(mo,mo,mi[vid*hM_],hM_); Exp(mo,mo,hM_); // alpha=exp(old-mi_new)

    for(int32_t h=0;h<hM_;++h){ float nm=-mi[vid*hM_+h].GetValue(0); Adds(sc[h*bn],sc[h*bn],nm,bn); }
    Exp(sc,sc,hRS); // P_temp=exp(S-mi_new)
    ReduceSum<float>(si,sc,rw,hM_,bn,bn,1); // sumexp_i

    LocalTensor<float> o=oBuf_.Get<float>();
    int32_t ob=vid*hM_*t_.dim;
    for(int32_t h=0;h<hM_;++h) Muls(o[ob+h*t_.dim],o[ob+h*t_.dim],mo[h],t_.dim);

    LocalTensor<float> se=seBuf_.Get<float>();
    Mul(se[vid*hM_],se[vid*hM_],mo,hM_); Add(se[vid*hM_],se[vid*hM_],si,hM_);

    int32_t po=ci_*t_.block_m*t_.block_n + vid*hRS;
    LocalTensor<half> pH; voQ_.AllocTensor<half>(pH);
    Cast(pH,sc,RoundMode::CAST_ROUND,hRS);
    voQ_.EnQue(pH); voQ_.DeQue<half>(pH);
    { GlobalTensor<half> w; w.SetGlobalBuffer(wPB_,t_.total_cores*t_.block_m*t_.block_n);
      faUbOut(w[po],pH,hRS*sizeof(half)); }
    voQ_.FreeTensor(pH);

    CrossCoreSetFlag<0x2,PIPE_MTE2>(FA_FLAG_P);
    CrossCoreWaitFlag<0x2>(FA_FLAG_O);
}

// ===== AIC Cons: P@V → O_tmp =====
__aicore__ inline void FlashAttentionScoreKernel::aicC(int32_t t)
{
    LocalTensor<half> pL1 = a1Q_.AllocTensor<half>(); // reuse A1 for P
    { GlobalTensor<half> w; w.SetGlobalBuffer(wPB_,t_.total_cores*t_.block_m*t_.block_n);
      int32_t po=ci_*t_.block_m*t_.block_n;
      faNd2Nz(pL1,w[po],t_.block_m,t_.block_n,t_.block_n); }
    a1Q_.EnQue(pL1);
    LocalTensor<half> pL1r = a1Q_.DeQue<half>();

    LocalTensor<half> vL1 = b1Q_.AllocTensor<half>();
    { GlobalTensor<half> vg; vg.SetGlobalBuffer(vB_,t_.batch*t_.seq_len*t_.dim);
      int32_t vo=bz_*t_.seq_len*t_.dim + t*t_.block_n*t_.dim;
      faNd2Nz(vL1,vg[vo],t_.block_n,t_.dim,t_.dim); }
    b1Q_.EnQue(vL1);
    LocalTensor<half> vL1r = b1Q_.DeQue<half>();

    int32_t ccP=t_.block_n/DEFAULT_C0_SIZE, ccV=t_.dim/DEFAULT_C0_SIZE;
    int32_t nC=(t_.dim+CBN-1)/CBN;
    LocalTensor<float> c1=c1Q_.AllocTensor<float>();
    for(int32_t nc=0; nc<nC; ++nc){
        int32_t no=nc*CBN, ns=(no+CBN>t_.dim)?(t_.dim-no):CBN; if(ns<=0)break;
        LocalTensor<half> a2=a2Q_.AllocTensor<half>();
        faL0A(a2,pL1r,t_.block_m,t_.block_n,ccP);
        LocalTensor<half> b2=b2Q_.AllocTensor<half>();
        faL0B(b2,vL1r[no/DEFAULT_C0_SIZE*ccV],ns,t_.block_n,ccV);
        PipeBarrier<PIPE_MTE3>();
        Mmad(c1[no/DEFAULT_C0_SIZE*t_.block_m],a2,b2,t_.block_m,t_.block_n,ns,(nc==0)?1:0);
        a2Q_.FreeTensor(a2); b2Q_.FreeTensor(b2);
    }

    c1Q_.EnQue(c1);
    LocalTensor<float> c1o=c1Q_.DeQue<float>();
    int32_t oo=ci_*t_.block_m*t_.dim;
    { GlobalTensor<float> w; w.SetGlobalBuffer(wOB_,t_.total_cores*t_.block_m*t_.dim);
      faFixpipe(w[oo],c1o,t_.block_m,t_.dim); }
    c1Q_.FreeTensor(c1o);
    a1Q_.FreeTensor(pL1r); b1Q_.FreeTensor(vL1r);

    CrossCoreSetFlag<0x2,PIPE_FIX>(FA_FLAG_O);
}

// ===== AIV Cons: merge O_tmp =====
__aicore__ inline void FlashAttentionScoreKernel::aivC(int32_t t)
{
    int32_t vid=GetSubBlockIdx();
    int32_t oco=ci_*t_.block_m*t_.dim, oof=oco+vid*hM_*t_.dim, oe=hM_*t_.dim;

    LocalTensor<float> oIn; viQ_.AllocTensor<float>(oIn);
    { GlobalTensor<float> w; w.SetGlobalBuffer(wOB_,t_.total_cores*t_.block_m*t_.dim);
      faUbIn(oIn,w[oof],oe*sizeof(float)); }
    viQ_.EnQue(oIn);

    LocalTensor<float> oT=otBuf_.Get<float>();
    viQ_.DeQue<float>(oIn);
    DataCopy(oT,oIn,oe);
    viQ_.FreeTensor(oIn);

    LocalTensor<float> o=oBuf_.Get<float>();
    int32_t ob=vid*hM_*t_.dim;
    Add(o[ob],o[ob],oT,oe);
}

// ===== AIV Epi =====
__aicore__ inline void FlashAttentionScoreKernel::aivEpi()
{
    int32_t vid=GetSubBlockIdx();
    LocalTensor<float> o=oBuf_.Get<float>(), se=seBuf_.Get<float>();
    int32_t ob=vid*hM_*t_.dim, seo=vid*hM_;
    for(int32_t h=0; h<hM_; ++h){
        float iv=1.0f/se[seo+h].GetValue(0);
        Muls(o[ob+h*t_.dim],o[ob+h*t_.dim],iv,t_.dim);
    }
    LocalTensor<half> oH; voQ_.AllocTensor<half>(oH);
    Cast(oH,o[ob],RoundMode::CAST_ROUND,hM_*t_.dim);
    voQ_.EnQue(oH); voQ_.DeQue<half>(oH);
    int32_t oo=bz_*t_.seq_len*t_.dim+(bx_*t_.block_m+vid*hM_)*t_.dim;
    { GlobalTensor<half> og; og.SetGlobalBuffer(oB_,t_.batch*t_.seq_len*t_.dim);
      faUbOut(og[oo],oH,hM_*t_.dim*sizeof(half)); }
    voQ_.FreeTensor(oH);
}

