 * Each core does Q@K^T → scale → softmax → @V entirely on UB.
 */

#ifndef FLASH_ATTENTION_SCORE_KERNEL_H
#define FLASH_ATTENTION_SCORE_KERNEL_H

#include "kernel_operator.h"
using namespace AscendC;
constexpr int32_t TK = 64;  // tile size along K dim for matmul
constexpr int32_t TN = 64;  // tile size along N dim for matmul

#pragma pack(push,8)
struct FlashAttentionTiling {
    int32_t batch,seq_len,dim,block_m,block_n,kv_loops,block_n_tail,m_blocks,total_cores;
    float scale_value;
};
#pragma pack(pop)

__aicore__ inline void faTcopy(FlashAttentionTiling*t,GM_ADDR gm){
    auto s=reinterpret_cast<__gm__ int32_t*>(gm);
    auto d=reinterpret_cast<int32_t*>(t);
    for(uint32_t i=0;i<sizeof(FlashAttentionTiling)/sizeof(int32_t);++i)d[i]=s[i];
}

// GM↔UB helpers
template<typename T>
__aicore__ inline void faG2U(LocalTensor<T>&l,const GlobalTensor<T>&g,uint32_t sz){
    DataCopyExtParams<T> e={1,static_cast<uint16_t>(sz*sizeof(T)/DEFAULT_C0_SIZE),0,0};
    DataCopyPadExtParams<T> p={false,0,0,0};
    DataCopyPad(l,g,e,p);
}
template<typename T>
__aicore__ inline void faU2G(const GlobalTensor<T>&g,LocalTensor<T>&l,uint32_t sz){
    DataCopyExtParams<T> e={1,static_cast<uint16_t>(sz*sizeof(T)/DEFAULT_C0_SIZE),0,0};
    DataCopyPad(g,l,e);
