// Per-row VecMatMul: C[cm] += A[am] * B^T[bn]
// A is [cm,dim] fp16 (cast to fp32 on read), B is [bn,dim] fp16
// Compute C[m,n] = sum_k A[m,k]*B[n,k]
template<typename AT, typename BT, typename CT>
__aicore__ inline void faVdot(CT&C,const AT&A,const BT&B,
    int32_t cm,int32_t bn,int32_t dim,TBuf<TPosition::VECCALC>&rw)
{
