{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * Licensed under CANN Open Software License Agreement Version 2.0.
 *
 * FlashAttentionScoreWithLargeHeadDim AscendC kernel.
 * Pure-Vector kernel — avoids Fixpipe CO1→GM which is unsupported on dav_m200.
 * Core algorithm: Q@K^T → scale → online softmax → @V → fp16 output.
 */

#ifndef FLASH_ATTENTION_SCORE_KERNEL_H
#define FLASH_ATTENTION_SCORE_KERNEL_H
#include "kernel_operator.h"
using namespace AscendC;

#pragma pack(push,8)
struct FlashAttentionTiling {
    int32_t batch,seq_len,dim,block_m,block_n,kv_loops,block_n_tail,m_blocks,total_cores;
    float scale_value;
};
#pragma pack(pop)

__aicore__ inline void faTcopy(FlashAttentionTiling*t,GM_ADDR gm){
    auto s=reinterpret_cast<__gm__ int32_t*>(gm);
    auto d=reinterpret_cast<int32_t*>(t);
    for(uint32_t i=0;i<sizeof(FlashAttentionTiling)/sizeof(int32_t);++i)d[i]=s[i];
}

class FlashAttentionScoreKernel {
public:
    __aicore__ inline void Init(GM_ADDR q,GM_ADDR k,GM_ADDR v,GM_ADDR o,
        GM_ADDR w0,GM_ADDR w1,GM_ADDR w2,GM_ADDR t,TPipe*p);
    __aicore__ inline void Process();
private:
    FlashAttentionTiling t_;
    int32_t bx_,bz_;
    __gm__ half* qB_,*kB_,*vB_,*oB_;

    TQue<TPosition::VECIN,0> viQ_;
    TQue<TPosition::VECOUT,0> voQ_;
    TBuf<TPosition::VECCALC> qBuf_,kBuf_,vBuf_;
    TBuf<TPosition::VECCALC> sBuf_,oBuf_,seBuf_,miBuf_,rwBuf_;
};

__aicore__ inline void FlashAttentionScoreKernel::Init(
    GM_ADDR q,GM_ADDR k,GM_ADDR v,GM_ADDR o,
    GM_ADDR w0,GM_ADDR w1,GM_ADDR w2,GM_ADDR t,TPipe* p)
{
    (void)w0;(void)w1;(void)w2;
    faTcopy(&t_,t);
    int32_t ci=GetBlockIdx();
    bz_=ci/t_.m_blocks; bx_=ci%t_.m_blocks;
    qB_=reinterpret_cast<__gm__ half*>(q); kB_=reinterpret_cast<__gm__ half*>(k);
    vB_=reinterpret_cast<__gm__ half*>(v); oB_=reinterpret_cast<__gm__ half*>(o);
    int32_t szQ=t_.block_m*t_.dim, szKN=t_.block_n*t_.dim;
    int32_t szS=t_.block_m*t_.block_n, szO=t_.block_m*t_.dim, szR=t_.block_m;
    p->InitBuffer(viQ_,1,szQ*sizeof(half)*2);
    p->InitBuffer(voQ_,1,szO*sizeof(half));
    p->InitBuffer(qBuf_,szQ*sizeof(float));
    p->InitBuffer(kBuf_,szKN*sizeof(float));
    p->InitBuffer(vBuf_,szKN*sizeof(float));
    p->InitBuffer(sBuf_,szS*sizeof(float));
    p->InitBuffer(oBuf_,szO*sizeof(float));
    p->InitBuffer(seBuf_,szR*sizeof(float));
    p->InitBuffer(miBuf_,szR*sizeof(float));
    p->InitBuffer(rwBuf_,szS*sizeof(float));
}

__aicore__ inline void FlashAttentionScoreKernel::Process()
{
    int32_t bc=t_.batch, sl=t_.seq_len, dim=t_.dim, bm=t_.block_m, bn=t_.block_n;
    int32_t kv=t_.kv_loops, bnt=t_.block_n_tail;

    // Init accumulators
    { LocalTensor<float> o=oBuf_.Get<float>(), se=seBuf_.Get<float>(), mi=miBuf_.Get<float>();
      Duplicate<float>(o,0.0f,bm*dim);
      Duplicate<float>(se,0.0f,bm);
      Duplicate<float>(mi,-1.0e30f,bm); }

    // Load Q to UB (fp16→fp32)
    LocalTensor<float> qF=qBuf_.Get<float>();
    { LocalTensor<half> qH; viQ_.AllocTensor<half>(qH);
      GlobalTensor<half> qg; qg.SetGlobalBuffer(qB_,bc*sl*dim);
      int32_t qo=bz_*sl*dim + bx_*bm*dim;
      DataCopyExtParams<half> e1; e1.blockCount=1;
      e1.blockLen=static_cast<uint16_t>(bm*dim*sizeof(half)/DEFAULT_C0_SIZE);
      e1.srcStride=0; e1.dstStride=0;
      DataCopyPadExtParams<half> p1={false,0,0,0};
      DataCopyPad(qH,qg[qo],e1,p1);
      viQ_.EnQue(qH); viQ_.DeQue<half>(qH);
      Cast(qF,qH,RoundMode::CAST_NONE,bm*dim);
      viQ_.FreeTensor(qH); }

    for(int32_t t=0; t<kv; ++t){
        int32_t cn=(t==kv-1&&bnt>0)?bnt:bn;

        // ---- Load K[t] → kF ----
        LocalTensor<float> kF=kBuf_.Get<float>();
        { LocalTensor<half> kH; viQ_.AllocTensor<half>(kH);
          GlobalTensor<half> kg; kg.SetGlobalBuffer(kB_,bc*sl*dim);
          int32_t ko=bz_*sl*dim + t*bn*dim;
          DataCopyExtParams<half> ek; ek.blockCount=1;
          ek.blockLen=static_cast<uint16_t>(cn*dim*sizeof(half)/DEFAULT_C0_SIZE);
          ek.srcStride=0; ek.dstStride=0;
          DataCopyPadExtParams<half> pk={false,0,0,0};
          DataCopyPad(kH,kg[ko],ek,pk);
          viQ_.EnQue(kH); viQ_.DeQue<half>(kH);
          Cast(kF,kH,RoundMode::CAST_NONE,cn*dim);
          viQ_.FreeTensor(kH); }

        // ---- S = Q@K^T ----
        LocalTensor<float> s=sBuf_.Get<float>();
        Duplicate<float>(s,0.0f,bm*cn);
        for(int32_t m=0;m<bm;++m){
            for(int32_t n=0;n<cn;++n){
                float acc=0.0f;
                for(int32_t d=0;d<dim;++d){
                    acc += qF[m*dim+d].GetValue(0) * kF[n*dim+d].GetValue(0);
                }
                s[m*cn+n].SetValue(0,acc*t_.scale_value);
            }
        }

        // ---- Online softmax ----
        { LocalTensor<float> o=oBuf_.Get<float>(), se=seBuf_.Get<float>();
          LocalTensor<float> mi=miBuf_.Get<float>(), rw=rwBuf_.Get<float>();

          for(int32_t m=0;m<bm;++m){
              // Row max
              float rowMax=-1.0e30f;
              for(int32_t j=0;j<cn;++j){float sv=s[m*cn+j].GetValue(0);if(sv>rowMax)rowMax=sv;}
              float oldM=mi[m].GetValue(0);
              float newM=(oldM>rowMax)?oldM:rowMax;
              mi[m].SetValue(0,newM);

              // alpha=exp(oldMax-newMax)
              float alpha=1.0f;
              if(oldM>-1.0e29f){
                  rw[m*bn].SetValue(0,oldM-newM);
                  Exp(rw[m*bn],rw[m*bn],1);
                  alpha=rw[m*bn].GetValue(0);
              }

              // S=exp(S-newMax), row sum
              for(int32_t j=0;j<cn;++j){rw[m*bn+j].SetValue(0,s[m*cn+j].GetValue(0)-newM);}
              Exp(rw[m*bn],rw[m*bn],cn);
              float rSum=0.0f;
              for(int32_t j=0;j<cn;++j){float ev=rw[m*bn+j].GetValue(0);s[m*cn+j].SetValue(0,ev);rSum+=ev;}

              // Rescale O, update sumexp
              for(int32_t d=0;d<dim;++d){o[m*dim+d].SetValue(0,o[m*dim+d].GetValue(0)*alpha);}
              se[m].SetValue(0,se[m].GetValue(0)*alpha + rSum);
          }}

        // ---- O_tmp = P@V ----
        LocalTensor<float> vF=vBuf_.Get<float>();
        { LocalTensor<half> vH; viQ_.AllocTensor<half>(vH);
          GlobalTensor<half> vg; vg.SetGlobalBuffer(vB_,bc*sl*dim);
          int32_t voo=bz_*sl*dim + t*bn*dim;
          DataCopyExtParams<half> ev; ev.blockCount=1;
          ev.blockLen=static_cast<uint16_t>(cn*dim*sizeof(half)/DEFAULT_C0_SIZE);
          ev.srcStride=0; ev.dstStride=0;
          DataCopyPadExtParams<half> pv={false,0,0,0};
          DataCopyPad(vH,vg[voo],ev,pv);
          viQ_.EnQue(vH); viQ_.DeQue<half>(vH);
          Cast(vF,vH,RoundMode::CAST_NONE,cn*dim);
          viQ_.FreeTensor(vH); }

        { LocalTensor<float> o=oBuf_.Get<float>();
          for(int32_t m=0;m<bm;++m){
            for(int32_t d=0;d<dim;++d){
                float acc=0.0f;
                for(int32_t n=0;n<cn;++n){
                    acc+=s[m*cn+n].GetValue(0) * vF[n*dim+d].GetValue(0);
                }
                o[m*dim+d].SetValue(0,o[m*dim+d].GetValue(0)+acc);
            }
          }}
    }

    // ---- Epilogue ----
    { LocalTensor<float> o=oBuf_.Get<float>(), se=seBuf_.Get<float>();
      for(int32_t m=0;m<bm;++m){
        float iv=1.0f/se[m].GetValue(0);
        for(int32_t d=0;d<dim;++d){o[m*dim+d].SetValue(0,o[m*dim+d].GetValue(0)*iv);}
      }}

    // Cast & write
    LocalTensor<half> oH; voQ_.AllocTensor<half>(oH);
    { LocalTensor<float> o=oBuf_.Get<float>();
      Cast(oH,o,RoundMode::CAST_ROUND,bm*dim); }
    voQ_.EnQue(oH); voQ_.DeQue<half>(oH);
    { GlobalTensor<half> og; og.SetGlobalBuffer(oB_,bc*sl*dim);
      int32_t oo=bz_*sl*dim + bx_*bm*dim;
      DataCopyExtParams<half> eo; eo.blockCount=1;
      eo.blockLen=static_cast<uint16_t>(bm*dim*sizeof(half)/DEFAULT_C0_SIZE);
      eo.srcStride=0; eo.dstStride=0;
      DataCopyPad(og[oo],oH,eo); }
    voQ_.FreeTensor(oH);
}

#endif
